/// Parse a ticket for owner review. No app state, storage or network access.
#[tauri::command(rename_all = "snake_case")]
fn remote_access_preview(
    window: WebviewWindow<impl tauri::Runtime>,
    link: String,
) -> Result<remote_access::RemotePreviewView, remote_access::ConnectionError> {
    reject_sealed_window(&window).map_err(|_| remote_access::ConnectionError::main_window_only())?;
    // Structured like remote_access_connect, so an expired link is "expired",
    // not "other".
    remote_access::preview_pairing_link(link.trim()).map_err(|error| remote_access::ConnectionError::from(&error))
}

/// Confirm a reviewed link and attach without restarting the app. Validation
/// happens before cancellation; persistence still owns REMOTE_CONFIG_LOCK.
#[tauri::command(rename_all = "snake_case")]
async fn remote_access_connect(
    window: WebviewWindow<impl tauri::Runtime>,
    app: AppHandle<impl tauri::Runtime>,
    state: State<'_, NodeState>,
    link: String,
) -> Result<RemoteImportView, remote_access::ConnectionError> {
    reject_sealed_window(&window).map_err(|_| remote_access::ConnectionError::main_window_only())?;
    drop(window);
    let dir = app.path().app_data_dir().map_err(|_| remote_access::ConnectionError::app_data_unavailable())?;
    remote_access_connect_at(&app, &state, &dir, &link).await
}

async fn remote_access_connect_at<R: tauri::Runtime>(
    app: &AppHandle<R>, state: &NodeState, dir: &Path, link: &str,
) -> Result<RemoteImportView, remote_access::ConnectionError> {
    use remote_access::{ConnectionError, RemoteError};
    let preview = remote_access::preview_pairing_link(link.trim()).map_err(|e| ConnectionError::from(&e))?;
    // This command is the join path. Desktop first-owner setup retains its
    // separate import/ceremony path; an unclaimed box must never be dialed here.
    if preview.first_run { return Err((&RemoteError::Unclaimed).into()); }
    let _change = state.remote_change.lock().await;
    #[cfg(all(desktop, not(feature = "mobile")))]
    if !state.remote_mode.load(Ordering::SeqCst)
        && (state.local_startup.load(Ordering::SeqCst)
            || state.config.lock().unwrap().is_some() || state.external_node.lock().unwrap().is_some())
    {
        return Err(ConnectionError::busy());
    }
    // Never switch a node underneath a money action or an enrollment ceremony.
    let _money = state.money.try_lock().map_err(|_| ConnectionError::busy())?;
    let mut devices = state.add_device.try_lock().map_err(|_| ConnectionError::busy())?;
    if devices.is_active() { return Err(ConnectionError::busy()); }
    #[cfg(all(desktop, not(feature = "mobile")))]
    let _owner = state.remote_owner.try_lock().map_err(|_| ConnectionError::busy())?;
    #[cfg(all(desktop, not(feature = "mobile")))]
    if _owner.is_active() || remote_owner::has_pending_recovery(&dir.join(PAIRING_STORE_DIR))
        .map_err(|_| ConnectionError::other())? { return Err(ConnectionError::busy()); }

    let next = remote_access::parse_pairing_link(link.trim()).map_err(|e| ConnectionError::from(&e))?;
    let previous_descriptor = state.remote_descriptor.lock().unwrap().clone()
        .or(remote_access::load_persisted(dir).map_err(|e| ConnectionError::from(&e))?);
    let changed_node = previous_descriptor.as_ref()
        .is_none_or(|old| remote_access::replaces_another_node(old, &next));
    state.remote_connect_generation.send_modify(|generation| *generation = generation.wrapping_add(1));
    let _recovery = state.remote_recovery.lock().await;
    let result = match remote_access::import_pairing_link(dir, link.trim()) {
        Ok(result) => result,
        Err(error) => {
            // Join teardown under remote_change/recovery, outside the spawned
            // task's cancellation select. A second Connect/Forget must wait for
            // the surviving listener and its sockets to close before rebinding.
            *state.ready.lock().unwrap() = false;
            let previous = state.remote_proxy.lock().unwrap().take();
            if let Some(proxy) = previous { proxy.stop_and_wait().await; }
            spawn_remote_connect(app, dir, true);
            return Err((&error).into());
        }
    };
    // Hide the old trust boundary before closing its sockets. No old approval,
    // bearer, readiness or identity may authorize work on the replacement.
    state.remote_connect_generation.send_modify(|generation| {
        *generation = generation.wrapping_add(1);
        *state.ready.lock().unwrap() = false;
        *state.auth.lock().unwrap() = AuthMode::Unauthenticated;
        *state.token.lock().unwrap() = None;
        *state.node_id.lock().unwrap() = None;
    });
    state.spend.lock().unwrap().lock();
    state.autopay.lock().unwrap().lock();
    *state.wants.lock().unwrap() = Wants::default();
    state.approvals_restored.store(false, Ordering::SeqCst);
    state.device_lapsed.store(false, Ordering::SeqCst);
    *state.node_grant.lock().unwrap() = None;
    *state.all_in_caps_node.lock().unwrap() = None;
    *state.readmission_ask.lock().unwrap() = None;
    *state.owner_contact.lock().unwrap() = None;
    *state.front_door_ask.lock().unwrap() = None;
    // Config fallbacks describe the old node; the remint cooldown also gates
    // paired auth. Neither its policy/network nor its cooldown transfers.
    *state.room_routing_policy.lock().unwrap() = None;
    *state.configured_network.lock().unwrap() = None;
    *state.last_remint.lock().unwrap() = None;
    *devices = add_device::Setup::default();
    state.second_join_complete.store(false, Ordering::SeqCst);
    let previous = state.remote_proxy.lock().unwrap().take();
    if let Some(proxy) = previous { proxy.stop_and_wait().await; }
    if changed_node { state.remote_retry.reset_for_replacement(); }
    *state.remote_descriptor.lock().unwrap() = None;
    *state.expected_remote_node_id.lock().unwrap() = None;
    *state.pairing.lock().unwrap() = None;
    *state.pairing_view.lock().unwrap() = PairingView::pending();
    *state.home_last_probe.lock().unwrap() = None;
    *state.home_attempts_left.lock().unwrap() = None;
    *state.home_unlock_state.lock().unwrap() = "ready";
    state.home_locked.store(false, Ordering::SeqCst);
    #[cfg(any(target_os = "android", all(target_os = "macos", desktop, not(feature = "mobile"))))]
    { *state.home_remember.lock().unwrap() = None; }
    state.stale_pairing.store(false, Ordering::SeqCst);
    // A new link is the owner's action: it may dial even after a refusal.
    state.remote_retry.clear_refusal();
    state.remote_mode.store(true, Ordering::SeqCst);
    *state.error.lock().unwrap() = None;
    state.remote_retry.clear_connection_error();
    // Subscribe while holding remote_change: Forget must invalidate even a
    // spawned task that has not been polled yet.
    spawn_remote_connect(app, dir, true);
    Ok(RemoteImportView { restart_required: false, ..result })
}

/// Validate and persist a confirmed ticket. Phones attach immediately; desktop
/// bootstrap selects the saved remote node on the next app start.
#[tauri::command(rename_all = "snake_case")]
async fn remote_access_import(
    window: WebviewWindow<impl tauri::Runtime>,
    app: AppHandle<impl tauri::Runtime>,
    state: State<'_, NodeState>,
    link: String,
) -> Result<RemoteImportView, String> {
    reject_sealed_window(&window)?;
    drop(window);
    let app_data_dir = app.path().app_data_dir()
        .map_err(|error| format!("no app data dir: {error}"))?;
    remote_access_import_at(&app, &state, &app_data_dir, &link).await
}

async fn remote_access_import_at<R: tauri::Runtime>(
    _app: &AppHandle<R>,
    state: &NodeState,
    app_data_dir: &Path,
    link: &str,
) -> Result<RemoteImportView, String> {
    // Validate before cancelling: a malformed ticket must not interrupt recovery.
    remote_access::preview_pairing_link(link.trim()).map_err(|error| error.to_string())?;
    #[cfg(any(mobile, feature = "mobile"))]
    let _change = state.remote_change.lock().await;
    // Reject a live trust-boundary switch without cancelling its recovery.
    if state.remote_proxy.lock().unwrap().is_some() {
        return Err("remote access is already active; quit BitSov before replacing its pairing link".into());
    }
    #[cfg(any(mobile, feature = "mobile"))]
    state.remote_connect_generation.send_modify(|generation| *generation = generation.wrapping_add(1));
    #[cfg(any(mobile, feature = "mobile"))]
    let _recovery = state.remote_recovery.lock().await;
    if state.remote_proxy.lock().unwrap().is_some() {
        // The old attach can publish a proxy between our first check and its
        // cancellation. Keep that trust boundary and resume the auth we stopped.
        #[cfg(any(mobile, feature = "mobile"))]
        spawn_remote_connect(_app, app_data_dir, false);
        return Err("remote access is already active; quit BitSov before replacing its pairing link".into());
    }
    let result = match remote_access::import_pairing_link(app_data_dir, link.trim()) {
        Ok(result) => result,
        Err(error) => {
            // Persistence is atomic: the previous saved ticket still owns this
            // connection. Cancellation must not leave its recovery stopped.
            #[cfg(any(mobile, feature = "mobile"))]
            spawn_remote_connect(_app, app_data_dir, true);
            return Err(error.to_string());
        }
    };
    #[cfg(any(mobile, feature = "mobile"))]
    {
        *state.error.lock().unwrap() = None;
        spawn_remote_connect(_app, app_data_dir, true);
        return Ok(RemoteImportView { restart_required: false, ..result });
    }
    #[cfg(not(any(mobile, feature = "mobile")))]
    Ok(result)
}

fn spawn_remote_connect<R: tauri::Runtime>(app: &AppHandle<R>, app_data_dir: &Path, wait: bool) {
    let mut cancelled = app.state::<NodeState>().remote_connect_generation.subscribe();
    let app = app.clone();
    let app_data_dir = app_data_dir.to_path_buf();
    tauri::async_runtime::spawn(async move {
        let state = app.state::<NodeState>();
        tokio::select! {
            biased;
            _ = cancelled.changed() => {},
            result = connect_remote_at(&state, &app_data_dir, wait) => {
                if let Err(error) = result { set_error(&state, error); }
            }
        }
    });
}

/// Forget the saved remote link for the next startup. Do not switch a live
/// connection (or its trust boundary) in place.
#[tauri::command]
async fn remote_access_forget(
    window: WebviewWindow<impl tauri::Runtime>,
    app: AppHandle<impl tauri::Runtime>,
) -> Result<(), String> {
    reject_sealed_window(&window)?;
    drop(window);
    let app_data_dir = app
        .path()
        .app_data_dir()
        .map_err(|error| format!("no app data dir: {error}"))?;
    remote_access_forget_at(&app.state::<NodeState>(), &app_data_dir).await
}

async fn remote_access_forget_at(state: &NodeState, app_data_dir: &Path) -> Result<(), String> {
    let _change = state.remote_change.lock().await;
    state.remote_connect_generation.send_modify(|generation| *generation = generation.wrapping_add(1));
    let _recovery = state.remote_recovery.lock().await;
    remote_access::forget_persisted(app_data_dir).map_err(|error| error.to_string())?;
    state.remote_retry.clear_refusal();
    // Preserve established connections (Forget still selects the next startup).
    // An unfinished attach, however, must leave no stale remote onboarding state.
    if state.remote_mode.load(Ordering::SeqCst) && state.remote_proxy.lock().unwrap().is_none() {
        *state.remote_descriptor.lock().unwrap() = None;
        *state.expected_remote_node_id.lock().unwrap() = None;
        *state.pairing.lock().unwrap() = None;
        *state.pairing_view.lock().unwrap() = PairingView::starting();
        *state.error.lock().unwrap() = None;
        state.remote_mode.store(state.remote_only, Ordering::SeqCst);
        state.remote_retry.clear_connection_error();
        #[cfg(all(desktop, not(feature = "mobile")))]
        set_error(state, "Restart BitSov to continue after forgetting the remote node.");
    }
    Ok(())
}

/// Reconnect the remote transport even if pairing already succeeded. Local
/// pairing retries only a failed ceremony; only a confirmed unknown local
/// client can discard its stored pairing. Never downgrades remote auth.
#[tauri::command(rename_all = "snake_case")]
async fn pairing_retry(
    app: AppHandle<impl tauri::Runtime>,
    window: WebviewWindow<impl tauri::Runtime>,
    state: State<'_, NodeState>,
) -> Result<PairingView, String> {
    reject_sealed_window(&window)?;
    drop(window);
    let app_data_dir = app.path().app_data_dir()
        .map_err(|error| format!("no app data dir: {error}"))?;
    pairing_retry_at(state.inner(), &app_data_dir).await
}

async fn pairing_retry_at(state: &NodeState, app_data_dir: &Path) -> Result<PairingView, String> {
    pairing_retry_as(state, app_data_dir, Interaction::User).await
}

async fn pairing_retry_as(state: &NodeState, app_data_dir: &Path, interaction: Interaction) -> Result<PairingView, String> {
    if state.remote_mode.load(Ordering::SeqCst)
        || remote_access::load_persisted(app_data_dir).map_err(|error| error.to_string())?.is_some()
    {
        // Desktop imports select the next startup when a local node is already
        // selected. Its API listener and authenticated state cannot switch live.
        #[cfg(all(desktop, not(feature = "mobile")))]
        if !state.remote_mode.load(Ordering::SeqCst)
            && (state.local_startup.load(Ordering::SeqCst)
                || state.config.lock().unwrap().is_some() || state.external_node.lock().unwrap().is_some())
        {
            return Err("Restart BitSov to connect to the saved remote node.".into());
        }
        connect_remote_with(state, app_data_dir, false, interaction).await?;
        return Ok(state.pairing_snapshot());
    }
    let ctx = state
        .pairing
        .lock()
        .unwrap()
        .clone()
        .ok_or_else(|| "pairing is not available yet: the node has not started".to_string())?;
    if state.pairing_view.lock().unwrap().state != "failed" {
        return Ok(state.pairing_snapshot());
    }
    if state.stale_pairing.swap(false, Ordering::SeqCst) {
        pairing::forget_pairing(&ctx.store);
    }
    finish_auth(state, &ctx.data_dir).await;
    Ok(state.pairing_snapshot())
}

/// `GET /onboarding/state`. `None` means the first-run funding flow has not been
/// started yet — the node answers 404 until `/onboarding/start` has run once.
#[tauri::command(rename_all = "snake_case")]
async fn fund_state(
    window: WebviewWindow<impl tauri::Runtime>,
    state: State<'_, NodeState>,
) -> Result<Option<FundState>, String> {
    reject_sealed_window(&window)?;
    drop(window);
    let (status, body) = call_api(
        state.inner(),
        reqwest::Method::GET,
        "/onboarding/state",
        None,
    )
    .await?;
    if status == reqwest::StatusCode::NOT_FOUND {
        return Ok(None);
    }
    let mut fund: FundState = decode("/onboarding/state", status, &body)?;
    fund.funded = fund.current_step == FUNDING_SEEN;
    Ok(Some(fund))
}

/// `POST /onboarding/start` with tier `full` — the fund-your-own-node path. The
/// node declares `deny_unknown_fields`, so the body carries exactly these two.
#[tauri::command(rename_all = "snake_case")]
async fn fund_start(
    window: WebviewWindow<impl tauri::Runtime>,
    state: State<'_, NodeState>,
    funding_amount_sats: u32,
) -> Result<FundState, String> {
    reject_sealed_window(&window)?;
    drop(window);
    if funding_amount_sats == 0 {
        return Err("the funding amount must be at least 1 sat".into());
    }
    let body = serde_json::json!({
        "tier": "full",
        "funding_amount_sats": funding_amount_sats,
    });
    let (status, text) = call_api(
        state.inner(),
        reqwest::Method::POST,
        "/onboarding/start",
        Some(body),
    )
    .await?;
    let mut fund: FundState = decode("/onboarding/start", status, &text)?;
    fund.funded = fund.current_step == FUNDING_SEEN;
    Ok(fund)
}

