/// Bootstrap and rc7 expose the same restore URL on different routers. A 404
/// on this probe alone selects the legacy live route; other failures stay errors.
#[cfg(all(desktop, not(feature = "mobile")))]
async fn bootstrap_restore_available(state: &NodeState) -> Result<Option<bool>, String> {
    let response = state
        .http
        .get(format!("{}/bootstrap/state", state.api_base))
        .timeout(Duration::from_secs(5))
        .send()
        .await
        .map_err(|e| format!("bootstrap state request failed: {e}"))?;
    let status = response.status();
    if status == reqwest::StatusCode::NOT_FOUND {
        return Ok(None);
    }
    let body = response
        .text()
        .await
        .map_err(|e| format!("bootstrap state response failed: {e}"))?;
    #[derive(Deserialize)]
    struct Bootstrap {
        state: String,
        can_restore: bool,
    }
    let bootstrap: Bootstrap = decode("/bootstrap/state", status, &body)?;
    if bootstrap.state != "bootstrap" {
        return Err("node returned an unknown bootstrap state".into());
    }
    Ok(Some(bootstrap.can_restore))
}

#[cfg(all(desktop, not(feature = "mobile")))]
async fn request_identity_restore(
    state: &NodeState,
    phrase: &str,
) -> Result<RestoreResponse, String> {
    if state.remote_mode.load(Ordering::SeqCst) {
        return Err("Identity restore is only available for the local supervised node.".into());
    }
    if state.owner.active.load(Ordering::SeqCst) {
        return Err("Use the local owner ceremony for a new identity. Restoring an existing owner identity requires the owner console.".into());
    }
    match bootstrap_restore_available(state).await? {
        Some(false) => {
            return Err("This bootstrap node is not accepting an identity restore.".into())
        }
        Some(true) => {} // Use the paired bootstrap token already held by the host.
        None => {}       // rc7: the live router exposes /identity/restore.
    }
    let (status, body) = call_api(
        state,
        reqwest::Method::POST,
        "/identity/restore",
        Some(serde_json::json!({ "mnemonic": phrase })),
    )
    .await?;
    if status == reqwest::StatusCode::NOT_FOUND {
        return Err("This node only supports restoring into an identity-free data directory in bootstrap mode.".into());
    }
    decode("/identity/restore", status, &body)
}

/// `POST /identity/restore` — hand a recovery phrase to the node, then restart it.
///
/// The phrase is a write-only input: it is passed straight through to the node
/// (which owns key material), is never logged, never persisted by this app, and
/// never echoed back — `RestoreOutcome` carries only the public node_id. The node's
/// own rejection messages identify bad words by index, not by content.
#[tauri::command(rename_all = "snake_case")]
#[cfg(all(desktop, not(feature = "mobile")))]
async fn identity_restore(
    window: WebviewWindow<impl tauri::Runtime>,
    app: AppHandle<impl tauri::Runtime>,
    state: State<'_, NodeState>,
    mnemonic: String,
) -> Result<RestoreOutcome, String> {
    reject_sealed_window(&window)?;
    drop(window);
    refuse_external(state.inner())?;
    let phrase = mnemonic.trim();
    let words = phrase.split_whitespace().count();
    if words != 12 && words != 24 {
        return Err("a recovery phrase is 12 or 24 words".into());
    }
    let restored = request_identity_restore(state.inner(), phrase).await?;

    // The node writes the phrase to its data dir and reports restart_required; the
    // restored identity only takes effect on the next start. Restart whoever answers
    // 3141 onto that identity — same data dir, no re-init.
    let mut restarted = false;
    if restored.restart_required {
        match restart_node(&app, &restored.node_id).await {
            Ok(did_restart) => restarted = did_restart,
            Err(e) => {
                let message = format!(
                    "the recovery phrase was saved, but the node did not come back: {e}. \
                     Quit and reopen BitSov to finish."
                );
                // Also record it on the node state so the boot screen can show it if
                // IdentityGate is not mounted; the renderer also keeps a restoreError.
                set_error(state.inner(), message.clone());
                return Err(message);
            }
        }
    }

    // Never report success (or restarted) against a random healthy loopback process.
    let live = match fetch_node_id(state.inner()).await {
        Ok(id) => id,
        Err(e) => {
            let message = format!(
                "the recovery phrase was saved, but the restored identity could not be confirmed: {e}.                  Quit and reopen BitSov to finish."
            );
            set_error(state.inner(), message.clone());
            return Err(message);
        }
    };
    if live != restored.node_id {
        let message = "the recovery phrase was saved, but 127.0.0.1:3141 still serves a different identity.              Quit and reopen BitSov to finish."
            .to_string();
        set_error(state.inner(), message.clone());
        return Err(message);
    }

    Ok(RestoreOutcome {
        node_id: restored.node_id,
        restart_required: restored.restart_required,
        restarted,
    })
}

#[cfg(any(mobile, feature = "mobile"))]
#[tauri::command(rename_all = "snake_case")]
async fn identity_restore(
    window: WebviewWindow<impl tauri::Runtime>,
    mnemonic: String,
) -> Result<RestoreOutcome, String> {
    reject_sealed_window(&window)?;
    drop(mnemonic);
    Err("Restore your node identity on the home node, not on this phone.".into())
}

// ---- control center reads (read / receive scope only) -----------------------
//
// Each command is one or two loopback GETs through `call_api`, projected by
// `bitsov_app::control` so no ciphertext, preimage, token or key reaches the
// renderer. Nothing here sends, pays, admits a peer or edits a room; those are
// the actions below, behind the owner's spend window.

fn now_ms() -> u64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_millis() as u64)
        .unwrap_or(0)
}

async fn get_json<T: serde::de::DeserializeOwned>(state: &NodeState, path: &str) -> Result<T, String> {
    let (status, body) = call_api(state, reqwest::Method::GET, path, None).await?;
    // Error text names the route, never the query (which may carry a peer id).
    let route = path.split('?').next().unwrap_or(path);
    decode(route, status, &body)
}

async fn read_node_overview(state: &NodeState) -> Result<control::NodeOverview, String> {
    let status: control::NodeStatusResponse = get_json(state, "/status").await?;
    // An invalid report is unknown, never permission to use a different chain.
    let network_reported = status.network.is_some();
    let mut overview = control::NodeOverview::from_status(status, now_ms());
    // Local seed labels need verified provenance, not a loopback URL alone.
    overview.custody_mode =
        control::custody_mode(overview.custody_mode, verified_local_node(state));
    // Only while the node answering is the LDK node that config started.
    if !network_reported && overview.lightning_backend.as_deref() == Some("ldk") {
        overview.network = state.configured_network.lock().unwrap().clone();
    }
    Ok(overview)
}

/// True when the process answering the IPv4 API endpoint is the live node this
/// host supervises — matched by the exact socket (`127.0.0.1` / `*`, not a sibling
/// `[::1]` listener on the same port), that process's pid and uid, and its open
/// data directory. An SSH forward or reverse proxy on loopback fails this check:
/// there is no supervised child, the child's PID is not the owner, or ownership
/// is ambiguous. Fail closed when evidence is missing.
#[cfg(any(mobile, feature = "mobile", not(unix)))]
fn verified_local_node(_state: &NodeState) -> bool {
    // No peer-uid proof is implemented here; never claim local custody.
    false
}

#[cfg(all(desktop, not(feature = "mobile"), unix))]
fn verified_local_node(state: &NodeState) -> bool {
    let Some(port) = loopback_api_port(&state.api_base) else {
        return false;
    };
    let guard = match state.child.lock() {
        Ok(g) => g,
        Err(_) => return false,
    };
    let Some(child) = guard.as_ref() else {
        return false;
    };
    if !child_is_live(child) {
        return false;
    }
    let child_pid = child.id();
    let our_uid = bitsov_ffi::effective_uid();

    // Unique IPv4 LISTEN owner for this port (excludes [::1]).
    let listeners = ipv4_api_listen_owners(port);
    if listeners.len() != 1 {
        return false;
    }
    let listener = &listeners[0];
    if listener.pid != child_pid || listener.uid != our_uid {
        return false;
    }

    // The socket a connect to api_base actually reaches must be that same process.
    let Some(peer) = connected_api_peer_owner(port) else {
        return false;
    };
    if peer.pid != child_pid || peer.uid != our_uid {
        return false;
    }

    // Data dir / config from the supervised start must belong to that process.
    let config = match state.config.lock() {
        Ok(guard) => guard.clone(),
        Err(_) => return false,
    };
    let Some(config) = config else {
        return false;
    };
    process_matches_node_config(child_pid, &config)
}

