// ---- AI track (main window) -------------------------------------------------
// The app is the broker (`bitsov_app::ai`). Reads go through the closed read
// broker with the paired token only; the rc7 `/auth/local` token is never used
// for them. A remote model is off unless this computer's `ai-providers.json`
// turns it on, and a send carries only a body the owner was just shown.

/// Pending disclosures. Host memory only; dropped on quit.
#[derive(Default)]
struct AiState {
    // Lock also serializes preferences and notice persistence with Forget/Append.
    threads: Mutex<std::collections::HashMap<&'static str, ai::threads::Thread>>,
    watches: Mutex<ai::watches::Engine>,
    disclosures: ai::Disclosures,
}

fn ai_config_dir(app: &AppHandle<impl tauri::Runtime>) -> Result<std::path::PathBuf, String> {
    app.path()
        .app_config_dir()
        .map_err(|_| "Could not find this app's config folder.".to_string())
}

fn ai_local_path(app: &AppHandle<impl tauri::Runtime>) -> Result<std::path::PathBuf, String> {
    Ok(ai_config_dir(app)?.join("ai-local.json"))
}

/// Remotes from `ai-providers.json` (off by default). Own-tier model name is
/// applied only when [`ai_provider_views`] finds a live loopback server.
fn ai_provider_set(app: &AppHandle<impl tauri::Runtime>) -> (Vec<ai::ProviderView>, Vec<ai::Remote>) {
    let dir = app.path().app_config_dir().ok();
    let file = dir
        .as_ref()
        .and_then(|dir| ai::load_providers_file(&dir.join("ai-providers.json")));
    // Do not attach a saved Own model here: a down server must not badge as ready (N2).
    ai::providers(file.as_ref(), None)
}

/// Provider list for the window: remotes from the settings file, plus Own with
/// a model name only when the saved pick resolves on loopback right now.
async fn ai_provider_views(app: &AppHandle<impl tauri::Runtime>) -> Vec<ai::ProviderView> {
    let (mut views, _remotes) = ai_provider_set(app);
    let saved = ai_local_path(app)
        .ok()
        .and_then(|path| ai::local::load_local_file(&path));
    let Some(saved) = saved else {
        return views;
    };
    match ai::local::resolve_saved(Some(&saved)).await {
        Some(choice) => {
            if let Some(local) = views.iter_mut().find(|v| v.kind == ai::ProviderKind::Local) {
                local.model = Some(choice.model);
                local.note = None;
            }
        }
        None => {
            if let Some(local) = views.iter_mut().find(|v| v.kind == ai::ProviderKind::Local) {
                local.model = None;
                local.note = Some(format!(
                    "Local model \"{}\" is unavailable. Start Ollama or llama.cpp on this computer, then Refresh.",
                    saved.model
                ));
            }
        }
    }
    views
}

/// Read one topic through the broker, off the async runtime.
async fn ai_read_topic(state: &NodeState, topic: ai::Topic, since_ms: Option<u64>) -> Result<ai::TopicRead, String> {
    ensure_fresh_token(state).await;
    let auth = node_auth(state);
    let base = state.api_base.clone();
    let proxy_auth = state
        .remote_mode
        .load(Ordering::SeqCst)
        .then(|| state.remote_proxy_auth.clone());
    tauri::async_runtime::spawn_blocking(move || {
        let audit = Arc::new(bitsov_app::jarvis::broker::StderrAudit);
        ai::read_topic_with_proxy_auth(auth, &base, audit, topic, since_ms, proxy_auth)
    })
    .await
    .map_err(|_| "The read did not finish.".to_string())
}

/// One topic from the node, as the broker projects it, with its freshness.
#[tauri::command(rename_all = "snake_case")]
async fn ai_read(
    window: WebviewWindow<impl tauri::Runtime>,
    state: State<'_, NodeState>,
    ai_state: State<'_, AiState>,
    topic: Option<ai::Topic>,
    since_ms: Option<u64>,
    assistant: Option<ai::assistants::Assistant>,
    thread: Option<ai::threads::Request>,
    local_turn: Option<ai::tool_loop::Request>,
    watch: Option<ai::watches::Poll>,
) -> Result<serde_json::Value, String> {
    reject_sealed_window(&window)?;
    if let Some(poll) = watch {
        if topic.is_some() || since_ms.is_some() || thread.is_some() || local_turn.is_some() {
            return Err("Choose a watch poll, a local model turn, a topic read, or a thread operation.".into());
        }
        let assistant = assistant.ok_or("Choose an assistant first.")?;
        // No timer or spawned task. Closed/hidden windows and quitting cannot evaluate,
        // persist, or catch up watches, even if an IPC was already queued.
        if state.quitting.load(Ordering::SeqCst) || !window.is_visible().unwrap_or(false) {
            ai_state.watches.lock().map_err(|_| "Watches are unavailable.")?.reset(assistant);
            return Ok(serde_json::Value::Null);
        }
        let mut settings = ai_state.threads.lock().map_err(|_| "Thread storage is unavailable.")?;
        let mut engine = ai_state.watches.lock().map_err(|_| "Watches are unavailable.")?;
        let dir = ai_config_dir(window.app_handle())?.join("ai-threads");
        #[cfg(all(target_os = "macos", not(feature = "mobile")))]
        let sealer: &dyn bitsov_app::at_rest::Sealer = {
            if !settings.contains_key(assistant.id()) {
                ai::threads::MacSealer.prepare(&dir);
            }
            &ai::threads::MacSealer
        };
        #[cfg(not(all(target_os = "macos", not(feature = "mobile"))))]
        let sealer = bitsov_app::at_rest::installed().ok_or("Sealed thread storage is unavailable on this platform.")?;
        let update = ai::threads::poll_watches(&dir, assistant, poll.revision.as_deref(), &poll.sample,
            &mut settings, &mut engine, true, now_ms(), sealer)?;
        return serde_json::to_value(update).map_err(|_| "Could not encode watch notices.".into());
    }
    if let Some(request) = local_turn {
        if topic.is_some() || since_ms.is_some() || thread.is_some() {
            return Err("Choose a local model turn, a topic read, or a thread operation.".into());
        }
        let assistant = assistant.ok_or("Choose an assistant first.")?;
        let path = ai_local_path(window.app_handle())?;
        drop(window);
        let saved = ai::local::load_local_file(&path).ok_or(ai::local::HOWTO)?;
        let choice = ai::local::resolve_saved(Some(&saved)).await.ok_or(ai::local::HOWTO)?;
        let turn = ai::tool_loop::run(assistant, &request.question, &request.draft_text,
            |body| ai::local::tool_completion(&choice, body),
            |topic, since| ai_read_topic(state.inner(), topic, since)).await?;
        if matches!(&turn.output, ai::tool_loop::Output::Proposal { .. }) {
            let contacts = with_book(state.inner(), false, |book| Ok(book.contacts.keys().cloned().collect::<Vec<_>>()))
                .map_err(|_| "Could not validate the draft against your local contact book.".to_string())?;
            turn.validate_contacts(&contacts)?;
        }
        return serde_json::to_value(turn).map_err(|_| "Could not encode the local answer.".into());
    }
    // Transcript operations reuse Ask's existing guarded command. No new ACL.
    if let Some(request) = thread {
        if topic.is_some() { return Err("Choose a topic read or a thread operation.".into()); }
        let assistant = assistant.ok_or("Choose an assistant first.")?;
        let mut settings = ai_state.threads.lock().map_err(|_| "Thread storage is unavailable.")?;
        let dir = ai_config_dir(window.app_handle())?.join("ai-threads");
        #[cfg(all(target_os = "macos", not(feature = "mobile")))]
        let sealer: &dyn bitsov_app::at_rest::Sealer = {
            // Forget must remain independent of decrypting the old transcript.
            if !matches!(&request, ai::threads::Request::Forget) {
                ai::threads::MacSealer.prepare(&dir);
            }
            &ai::threads::MacSealer
        };
        #[cfg(not(all(target_os = "macos", not(feature = "mobile"))))]
        let sealer = bitsov_app::at_rest::installed().ok_or("Sealed thread storage is unavailable on this platform.")?;
        let changed_rule = match &request { ai::threads::Request::SetWatch { rule, .. } => Some(*rule), _ => None };
        let saved = ai::threads::apply(&dir, assistant, request, sealer)?;
        settings.insert(assistant.id(), saved.clone());
        if let Some(rule) = changed_rule { ai_state.watches.lock().map_err(|_| "Watches are unavailable.")?.reset_rule(rule); }
        return serde_json::to_value(saved).map_err(|_| "Could not read the assistant thread.".into());
    }
    let topic = topic.ok_or("Choose a read topic.")?;
    if let Some(assistant) = assistant { assistant.authorize(topic)?; }
    drop(window);
    serde_json::to_value(ai_read_topic(state.inner(), topic, since_ms).await?)
        .map_err(|_| "Could not encode the read.".into())
}

/// Local first; remote ones say whether they are on and where they would send.
/// Own shows a model name only when the loopback server answers right now.
#[tauri::command(rename_all = "snake_case")]
async fn ai_providers(
    window: WebviewWindow<impl tauri::Runtime>,
) -> Result<Vec<ai::ProviderView>, String> {
    reject_sealed_window(&window)?;
    let app = window.app_handle().clone();
    drop(window);
    Ok(ai_provider_views(&app).await)
}

/// Prepare, never send: re-read the topic, narrow it, build the exact body,
/// and hold it for one send. Own-tier loopback models use the same hold/send
/// path so the owner always sees the exact bytes before anything is posted.
#[tauri::command(rename_all = "snake_case")]
#[allow(clippy::too_many_arguments)]
async fn ai_disclose(
    window: WebviewWindow<impl tauri::Runtime>,
    state: State<'_, NodeState>,
    ai_state: State<'_, AiState>,
    provider: ai::ProviderKind,
    topic: ai::Topic,
    since_ms: Option<u64>,
    preset: ai::Preset,
    question: String,
    assistant: Option<ai::assistants::Assistant>,
) -> Result<ai::Disclosure, String> {
    reject_sealed_window(&window)?;
    if let Some(assistant) = assistant { assistant.authorize_model(provider, topic)?; }
    let remote = match provider {
        ai::ProviderKind::Local => {
            let path = ai_local_path(window.app_handle())?;
            let saved = ai::local::load_local_file(&path)
                .ok_or_else(|| ai::local::HOWTO.to_string())?;
            let choice = ai::local::resolve_saved(Some(&saved))
                .await
                .ok_or_else(|| ai::local::HOWTO.to_string())?;
            choice.as_remote()
        }
        other => ai_provider_set(window.app_handle())
            .1
            .into_iter()
            .find(|remote| remote.kind == other)
            .ok_or("That model is off on this computer. Nothing was prepared.")?,
    };
    drop(window);
    let question = ai::clean_question(&question).ok_or("Ask a question first.")?;
    let read = ai_read_topic(state.inner(), topic, since_ms).await?;
    let body = ai::request_body(&remote, &question, &read, preset)
        .ok_or("Your node could not be read, so nothing was prepared.")?;
    ai_state
        .disclosures
        .hold(&remote, preset, body, Instant::now())
        .ok_or_else(|| "Could not prepare the request.".to_string())
}

/// The owner's tap: send the held body, once.
#[tauri::command(rename_all = "snake_case")]
async fn ai_send(
    window: WebviewWindow<impl tauri::Runtime>,
    ai_state: State<'_, AiState>,
    disclosure_id: String,
) -> Result<ai::RemoteAnswer, String> {
    reject_sealed_window(&window)?;
    drop(window);
    let (remote, body) = ai_state
        .disclosures
        .take(&disclosure_id, Instant::now())
        .ok_or("That preview expired or was already used. Nothing was sent.")?;
    let key = remote.key_env.as_deref().and_then(|name| std::env::var(name).ok());
    ai::send(&remote, body, key).await
}

/// Drop a prepared request unsent.
#[tauri::command(rename_all = "snake_case")]
fn ai_cancel(
    window: WebviewWindow<impl tauri::Runtime>,
    ai_state: State<'_, AiState>,
    disclosure_id: String,
) -> Result<bool, String> {
    reject_sealed_window(&window)?;
    Ok(ai_state.disclosures.cancel(&disclosure_id))
}

/// Probe loopback for Ollama / llama.cpp; list models or return a short how-to.
#[tauri::command(rename_all = "snake_case")]
async fn ai_local_status(
    window: WebviewWindow<impl tauri::Runtime>,
    port: Option<u16>,
) -> Result<ai::local::LocalStatus, String> {
    reject_sealed_window(&window)?;
    let saved = ai_local_path(window.app_handle())
        .ok()
        .and_then(|path| ai::local::load_local_file(&path));
    let preferred = port.or_else(|| saved.as_ref().map(|s| s.port));
    let probe = ai::local::probe(preferred).await;
    Ok(ai::local::status_from(probe, saved.as_ref()))
}

/// Remember which loopback model Own should use. Remotes stay off.
#[tauri::command(rename_all = "snake_case")]
async fn ai_local_select(
    window: WebviewWindow<impl tauri::Runtime>,
    model: String,
    port: Option<u16>,
) -> Result<Vec<ai::ProviderView>, String> {
    reject_sealed_window(&window)?;
    let path = ai_local_path(window.app_handle())?;
    let preferred = port.or_else(|| ai::local::load_local_file(&path).map(|s| s.port));
    let probe = ai::local::probe(preferred)
        .await
        .ok_or_else(|| ai::local::HOWTO.to_string())?;
    let model = ai::short(&model, 80).ok_or("Pick a model name.")?;
    if !probe.models.iter().any(|name| name == &model) {
        return Err("That model is not on the local server right now.".into());
    }
    let file = ai::local::LocalFile {
        // Always the port that answered (N1): a dead typed port must not stick.
        port: probe.port,
        model,
        kind: Some(probe.kind),
    };
    ai::local::save_local_file(&path, &file)?;
    Ok(ai_provider_views(window.app_handle()).await)
}

/// Clear the Own model pick; answers fall back to rules on this computer.
#[tauri::command(rename_all = "snake_case")]
async fn ai_local_clear(
    window: WebviewWindow<impl tauri::Runtime>,
) -> Result<Vec<ai::ProviderView>, String> {
    reject_sealed_window(&window)?;
    let path = ai_local_path(window.app_handle())?;
    ai::local::clear_local_file(&path)?;
    Ok(ai_provider_views(window.app_handle()).await)
}

struct CallObservation {
    offer: spend_journal::OperationRecord,
    ended: bool,
}

fn capture_call_observation(state: &NodeState, event: &control::LiveEvent) -> Result<Option<CallObservation>, ActionError> {
    let control::LiveEvent::Message { message, room_id: None } = event else { return Ok(None) };
    if !matches!(message.kind, 401 | 403) { return Ok(None); }
    let Some(node_id) = state.node_id.lock().unwrap().clone() else { return Ok(None) };
    if message.recipient != node_id || message.sender == node_id { return Ok(None); }
    let Some(payload) = message.plaintext.as_deref()
        .and_then(|s| serde_json::from_str::<serde_json::Value>(s).ok()) else { return Ok(None) };
    if payload["v"] != 1 { return Ok(None); }
    let Some(call_id) = payload["call_id"].as_str() else { return Ok(None) };
    if call_id.len() != 32 || !call_id.bytes().all(|c| c.is_ascii_hexdigit() && !c.is_ascii_uppercase()) {
        return Ok(None);
    }
    if message.kind == 401 && payload["sdp"].as_str().is_none_or(str::is_empty) { return Ok(None); }
    let Some(dir) = app_files_dir(state) else { return Ok(None) };
    let Some(offer) = spend_journal::read_completed_call_admission(&dir.join("app-spend"), &node_id, &message.sender, call_id)?
        else { return Ok(None) };
    Ok(Some(CallObservation { offer, ended: message.kind == 403 }))
}

async fn persist_call_observation(state: &NodeState, observation: &CallObservation) -> Result<bool, ActionError> {
    let _money = state.money.lock().await;
    if state.node_id.lock().unwrap().as_deref() != Some(&observation.offer.node_id) { return Ok(false); }
    let journal = locked_spend_journal(state)?;
    let current = journal.operation_record(&observation.offer.op_id)?;
    if current.is_none_or(|r| r.created_ms != observation.offer.created_ms) { return Ok(false); }
    journal.observe_call(&observation.offer, observation.ended)?;
    Ok(true)
}

/// Carry the receive-time binding to the renderer; it never resolves a wire
/// call id into payment authority. Missing/stale observations serialize as null.
fn bind_call_event(event: &mut control::LiveEvent, observation: Option<&CallObservation>) {
    if let control::LiveEvent::Message { message, .. } = event {
        message.admission_operation_id = observation.filter(|o| !o.offer.call_closed)
            .map(|o| o.offer.op_id.clone());
    }
}

/// Tauri event the main window listens on for `/ws` traffic.
const LIVE_EVENT: &str = "node-live";

/// Forward to the MAIN window only. The sealed assistant window never receives
/// node traffic, which carries decrypted plaintext. Link transitions are
/// recorded on the way, so `live_link` can replay them to a late subscriber.
fn emit_live<R: tauri::Runtime>(app: &AppHandle<R>, event: control::LiveEvent) {
    app.state::<NodeState>().live_link.publish(event, |event| {
        let _ = app.emit_to(MAIN_WINDOW_LABEL, LIVE_EVENT, event);
    });
}

/// Re-send the current `/ws` link state on `node-live`, to the main window only.
///
/// The bridge reports `open` once, when the socket opens, which is usually before
/// the shell has mounted and subscribed. The shell calls this right after it
/// subscribes. The replay goes out on the same channel as live transitions, and
/// under the same lock, so it can never land after a newer one.
#[tauri::command(rename_all = "snake_case")]
fn live_link(
    window: WebviewWindow<impl tauri::Runtime>,
    state: State<'_, NodeState>,
) -> Result<Option<control::LinkState>, String> {
    reject_sealed_window(&window)?;
    Ok(state.live_link.replay(|event| {
        let _ = window.emit_to(MAIN_WINDOW_LABEL, LIVE_EVENT, event);
    }))
}

/// Bridge the node's loopback `GET /ws` into the main window.
///
/// The HOST holds the socket and the token (presented as `?token=`, which the
/// node accepts alongside the `bitsov.jwt.` subprotocol); the renderer only sees
/// parsed [`control::LiveEvent`]s. Waits for the node to be ready, reconnects
/// with backoff, and stops once the app is quitting.
async fn live_bridge(app: AppHandle) {
    let state = app.state::<NodeState>();
    let session_identity = Mutex::new(None::<String>);
    let (events, mut received) = tokio::sync::mpsc::unbounded_channel();
    let forward = |event| {
        // Old socket traffic must not acquire a replacement node's authority.
        let same_identity = *session_identity.lock().unwrap() == *state.node_id.lock().unwrap();
        let observation = if same_identity { capture_call_observation(&state, &event) } else { Ok(None) };
        let _ = events.send((event, observation));
    };
    let stopping = || state.quitting.load(Ordering::SeqCst);
    let feed = control::run_live_feed(
        || async {
            if state.remote_mode.load(Ordering::SeqCst) && state.remote_retry.is_retrying() {
                let _ = reconnect_remote_background(&state).await;
            }
            if !*state.ready.lock().unwrap() { return Ok(None); }
            ensure_fresh_token(&state).await;
            let Some(token) = state.token.lock().unwrap().clone() else { return Ok(None); };
            let url = control::ws_url(&state.api_base, &token)?;
            *session_identity.lock().unwrap() = state.node_id.lock().unwrap().clone();
            Ok(Some((url, state.remote_proxy_auth.to_string())))
        },
        &forward,
        &stopping,
    );
    let process = forward_live_events(&state, &mut received, |event| emit_live(&app, event));
    tokio::select! { _ = feed => {}, _ = process => {} }
}

/// Drain receive-time observations in order. Idle time and link outages carry
/// no closure authority; only an observed node event can update admission.
async fn forward_live_events(
    state: &NodeState,
    received: &mut tokio::sync::mpsc::UnboundedReceiver<(control::LiveEvent, Result<Option<CallObservation>, ActionError>)>,
    mut emit: impl FnMut(control::LiveEvent),
) {
    while let Some((mut event, observation)) = received.recv().await {
        let result = match &observation {
            Ok(Some(observation)) => persist_call_observation(state, observation).await,
            Ok(None) => Ok(false),
            Err(error) => Err(error.clone()),
        };
        if result.is_err() { eprintln!("call ledger: could not persist live call observation"); }
        bind_call_event(&mut event, if matches!(result, Ok(true)) {
            observation.as_ref().ok().and_then(Option::as_ref)
        } else { None });
        emit(event);
    }
}

/// What a stop attempt actually did. Returned so the REAL adapter can be asserted
/// against disposable subprocesses, not just an injectable policy (app #16 review).
#[cfg(all(desktop, not(feature = "mobile")))]
#[derive(Debug, PartialEq, Eq)]
enum StopOutcome {
    /// The process had already exited — nothing was signalled.
    AlreadyExited,
    /// SIGTERM was sent and the process exited within the budget.
    TermedAndExited,
    /// SIGTERM was sent, the budget elapsed, SIGKILL finished the job.
    Killed,
}

/// Stop the node this app spawned: SIGTERM, bounded wait, SIGKILL as a last resort.
///
/// Ownership is structural, not checked. `SharedChild` waits with POSIX `waitid`,
/// which reaps WITHOUT releasing the pid for reuse, so `send_signal` cannot land on
/// an unrelated process — and it is documented to be a no-op once the child has been
/// waited on. That closes the check-then-signal race a `ps`-based ownership test
/// could only narrow: there is no window between "still ours" and "signal sent",
/// because the pid is not returned to the OS while we hold this handle.
///
/// We never hunt for whoever holds port 3141 — a node the app did not start belongs
/// to someone else and must survive our quit.
///
/// The graceful step matters: the node's own shutdown path (konsensus-node `main.rs`,
/// comment L0e) stops the Lightning backend explicitly because "LDK queues
/// ChannelMonitor persistence calls during shutdown; if we wait for Drop ... those
/// persistence calls can be silently lost — real-fund-loss class on a live channel".
/// It allows itself 15s for that, so the SIGKILL fallback sits beyond it. rc7 installs
/// a real `SignalKind::terminate()` handler, so SIGTERM lands on an orderly path.
///
/// Returns once the process is confirmed gone.
#[cfg(all(desktop, not(feature = "mobile")))]
fn stop_supervised_node(child: &SharedChild, budget: Duration) -> StopOutcome {
    if matches!(child.try_wait(), Ok(Some(_))) {
        return StopOutcome::AlreadyExited;
    }

    // Unix: ask politely first. No-op if the child was reaped between the check above
    // and here — the guarantee `ps`-based ownership could not give us.
    #[cfg(unix)]
    {
        let _ = child.send_signal(libc::SIGTERM);
        match child.wait_timeout(budget) {
            Ok(Some(_)) => return StopOutcome::TermedAndExited,
            _ => {
                eprintln!(
                    "[node] pid {} ignored SIGTERM for {budget:?}; escalating",
                    child.id()
                );
            }
        }
    }

    // Windows has no SIGTERM: `TerminateProcess` (what `kill` maps to) is the only
    // stop available, so there is no graceful step to skip — we go straight to it
    // rather than silently doing nothing on that platform. The node therefore does
    // not get to flush LDK ChannelMonitor state on Windows; that is a real gap and
    // belongs to whatever ticket makes Windows a supported target (it is not one
    // today — the Windows sidecar is unsigned and untested). Kept explicit here so
    // it is visible rather than implied by an absent branch.
    #[cfg(not(unix))]
    let _ = budget;

    let _ = child.kill();
    let _ = child.wait(); // confirm completion rather than assume it
    StopOutcome::Killed
}

/// Registration of the supervised node, coordinated with quit (Codex R2G on 3ff4e60e).
///
/// The hazard: the host process ends as soon as the exit handler returns, taking every
/// other thread with it. So whatever the exit handler cannot see — a node deregistered
/// by a restore that is still stopping it, or a node spawned after the handler ran —
/// outlives the app with the user's keys loaded.
#[cfg(all(desktop, not(feature = "mobile")))]
impl NodeState {
    /// Spawn the node and register it in one step, unless quit has begun. The check and
    /// the registration happen under the lock the exit handler takes, so either the node
    /// is registered before quit looks (and quit stops it), or quit came first and
    /// nothing is spawned.
    fn spawn_child(&self, cmd: &mut std::process::Command) -> Result<Arc<SharedChild>, String> {
        self.require_local_node()?;
        let mut slot = self.child.lock().unwrap();
        if self.quitting.load(Ordering::SeqCst) {
            return Err("the app is quitting; the node was not started".into());
        }
        let child =
            Arc::new(SharedChild::spawn(cmd).map_err(|e| format!("node start failed: {e}"))?);
        self.sidecar_terminated.store(false, Ordering::SeqCst);
        self.initialization_refused.store(false, Ordering::SeqCst);
        self.price_floor_refused.store(false, Ordering::SeqCst);
        *slot = Some(child.clone());
        Ok(child)
    }

    fn record_node_exit(&self, child: &Arc<SharedChild>, initialization_refused: bool, price_floor_refused: bool) {
        let slot = self.child.lock().unwrap();
        if slot.as_ref().is_some_and(|current| Arc::ptr_eq(current, child)) {
            self.initialization_refused.store(initialization_refused, Ordering::SeqCst);
            self.price_floor_refused.store(price_floor_refused, Ordering::SeqCst);
            self.sidecar_terminated.store(true, Ordering::SeqCst);
        }
    }

    /// Stop the registered node ahead of a restart. It stays registered for the whole
    /// stop — up to `budget` — and is deregistered only once its exit is confirmed, and
    /// only if the slot still holds it (quit may have taken it meanwhile).
    ///
    /// Returns whether there was a node to stop.
    fn stop_for_restart(&self, budget: Duration) -> bool {
        // A restored/adopted listener may share identity and backend with the
        // old node without sharing its startup configuration.
        *self.room_routing_policy.lock().unwrap() = None;
        *self.configured_network.lock().unwrap() = None;
        let Some(child) = self.child.lock().unwrap().as_ref().cloned() else {
            return false;
        };
        stop_supervised_node(&child, budget);
        let mut slot = self.child.lock().unwrap();
        if slot.as_ref().is_some_and(|c| Arc::ptr_eq(c, &child)) {
            *slot = None;
        }
        true
    }

    /// The exit handler: refuse any further spawn, then stop the registered node —
    /// including one a restore is still stopping — and return only once it is confirmed
    /// gone. `take()` makes a repeated shutdown event a no-op: the second finds `None`.
    fn stop_for_quit(&self, budget: Duration) -> Option<StopOutcome> {
        let child = {
            let mut slot = self.child.lock().unwrap();
            self.quitting.store(true, Ordering::SeqCst);
            slot.take()
        };
        child.map(|child| stop_supervised_node(&child, budget))
    }
}

// ---- M6 A1: node-routed call media ------------------------------------------

/// One open media session: the host-owned socket task for one call id.
struct MediaSession {
    #[allow(dead_code)]
    call_id: String,
    uplink: Arc<control::media::FrameQueue>,
    stop: Arc<AtomicBool>,
}

/// Stop the current media session, if any. Idempotent; the socket task sees
/// the flag, closes its socket and reports `ended` on its channel.
fn stop_media_session(state: &NodeState) {
    if let Some(session) = state.media.lock().unwrap().take() {
        session.stop.store(true, Ordering::SeqCst);
        session.uplink.clear();
    }
}

/// Own one media socket for the app the way `live_bridge` owns `/ws`: wait for
/// the node, present the current token and the loopback proxy credential,
/// reconnect with backoff, and stop on a refusal, on `stop`, or when the app
/// quits. Frames from the node reach the renderer through a bounded
/// drop-oldest queue drained into the channel; link transitions go as JSON.
async fn media_bridge<R: tauri::Runtime>(
    app: AppHandle<R>,
    call_id: String,
    peer: String,
    uplink: Arc<control::media::FrameQueue>,
    stop: Arc<AtomicBool>,
    channel: tauri::ipc::Channel<tauri::ipc::InvokeResponseBody>,
) {
    let state = app.state::<NodeState>();
    let downlink = control::media::FrameQueue::new(control::media::QUEUE_FRAMES);
    let stopping = || stop.load(Ordering::SeqCst) || state.quitting.load(Ordering::SeqCst);
    let emit = |link: control::media::MediaLink| {
        let _ = channel.send(tauri::ipc::InvokeResponseBody::Json(link.to_json()));
    };
    let link = control::media::run_media_link(
        || async {
            if !*state.ready.lock().unwrap() { return Ok(None); }
            ensure_fresh_token(&state).await;
            let Some(token) = state.token.lock().unwrap().clone() else { return Ok(None); };
            let url = control::media::media_url(&state.api_base, &call_id, &peer)?;
            Ok(Some((url, token, state.remote_proxy_auth.to_string())))
        },
        &uplink,
        &downlink,
        &emit,
        &stopping,
    );
    let drain = async {
        loop {
            let frame = downlink.pop().await;
            if channel.send(tauri::ipc::InvokeResponseBody::Raw(frame)).is_err() { break; }
        }
    };
    tokio::select! { _ = link => {}, _ = drain => {} }
    // Release only this session's slot: a newer session may have replaced it.
    let mut slot = state.media.lock().unwrap();
    if slot.as_ref().is_some_and(|session| Arc::ptr_eq(&session.stop, &stop)) {
        *slot = None;
    }
}

/// Open the host-owned media socket for `call_id` with `peer`, the call's
/// counterparty (M6 A1). Frames the node delivers arrive on `on_frame` as raw
/// bytes (seq + payload); link transitions arrive as JSON objects
/// (`{"link": …, "detail": …}`). One session at a time: opening replaces the
/// previous one. No payment and no admission change here: the node admits the
/// socket only for a `(peer, call_id)` it already knows, under the owner's token.
#[tauri::command(rename_all = "snake_case")]
async fn call_media_open(
    window: WebviewWindow<impl tauri::Runtime>,
    app: AppHandle<impl tauri::Runtime>,
    state: State<'_, NodeState>,
    call_id: String,
    peer: String,
    on_frame: tauri::ipc::Channel<tauri::ipc::InvokeResponseBody>,
) -> Result<(), String> {
    reject_sealed_window(&window)?;
    drop(window);
    let call_id = control::media::call_id(&call_id)?;
    let peer = control::media::peer_id(&peer)?;
    let uplink = Arc::new(control::media::FrameQueue::new(control::media::QUEUE_FRAMES));
    let stop = Arc::new(AtomicBool::new(false));
    stop_media_session(state.inner());
    *state.media.lock().unwrap() = Some(MediaSession { call_id: call_id.clone(), uplink: uplink.clone(), stop: stop.clone() });
    tauri::async_runtime::spawn(media_bridge(app, call_id, peer, uplink, stop, on_frame));
    Ok(())
}

/// The payload bytes of one `call_media_send` request: raw, or a byte array
/// on an IPC path that cannot carry raw bodies.
fn media_payload(body: &tauri::ipc::InvokeBody) -> Result<Vec<u8>, String> {
    let payload = match body {
        tauri::ipc::InvokeBody::Raw(bytes) => bytes.clone(),
        tauri::ipc::InvokeBody::Json(value) => serde_json::from_value::<Vec<u8>>(value.clone())
            .map_err(|_| "the media payload must be raw bytes".to_string())?,
    };
    if payload.is_empty() || payload.len() > control::media::MAX_PAYLOAD {
        return Err("the media payload is empty or too large".into());
    }
    Ok(payload)
}

/// One uplink payload for the open media session (raw bytes, no JSON). The
/// host assigns `seq`; a full queue drops its oldest frame rather than stall.
#[tauri::command(rename_all = "snake_case")]
fn call_media_send(
    window: WebviewWindow<impl tauri::Runtime>,
    state: State<'_, NodeState>,
    request: tauri::ipc::Request<'_>,
) -> Result<(), String> {
    reject_sealed_window(&window)?;
    let payload = media_payload(request.body())?;
    let slot = state.media.lock().unwrap();
    let Some(session) = slot.as_ref() else { return Err("no media session is open".into()) };
    session.uplink.push(payload);
    Ok(())
}

/// Close the open media session (hangup or local teardown). Idempotent; only
/// the socket closes, nothing is sent to the node and nothing is paid.
#[tauri::command(rename_all = "snake_case")]
fn call_media_close(window: WebviewWindow<impl tauri::Runtime>, state: State<'_, NodeState>) -> Result<(), String> {
    reject_sealed_window(&window)?;
    stop_media_session(state.inner());
    Ok(())
}

/// Local audio policy only: no node request, payment, or admission mutation.
#[tauri::command]
async fn call_audio_session(window: WebviewWindow<impl tauri::Runtime>, live: bool) -> Result<(), String> {
    reject_sealed_window(&window)?;
    #[cfg(target_os = "ios")]
    {
        let (send, receive) = tokio::sync::oneshot::channel();
        window.app_handle().run_on_main_thread(move || {
            let _ = send.send(bitsov_ffi::call_audio::set_live(live));
        }).map_err(|error| error.to_string())?;
        receive.await.map_err(|_| "Call audio dispatcher closed.".to_string())?
    }
    #[cfg(not(target_os = "ios"))]
    { let _ = (window, live); Ok(()) }
}

pub(super) fn entry() {
    #[cfg(target_os = "ios")]
    bitsov_ffi::pairing_link::install(|url| crate::pairing_link_ios::receive([url]));
    run();
}

fn run() {
    // Assistant mock path: sealed window only. Never construct NodeState (that
    // builds a reqwest client), never register wallet commands, never spawn the
    // node. Release and ordinary debug builds take `app_builder` below.
    //
    // One `generate_context!` only: a second expansion duplicates the embedded
    // Info.plist symbol when `--features sit-mock` compiles both paths.
    #[cfg(all(desktop, not(feature = "mobile"), debug_assertions, feature = "sit-mock"))]
    let builder = if assistant_dev_enabled() {
        assistant_mock_builder()
    } else {
        app_builder()
    };
    #[cfg(not(all(
        desktop,
        not(feature = "mobile"),
        debug_assertions,
        feature = "sit-mock"
    )))]
    let builder = app_builder();

    let app = builder
        .build(tauri::generate_context!())
        .expect("error building bitsov-app");

    #[cfg(all(desktop, not(feature = "mobile"), debug_assertions, feature = "sit-mock"))]
    if assistant_dev_enabled() {
        app.run(|_app, _event| {});
        return;
    }

    app.run(|app, event| {
        #[cfg(target_os = "ios")]
        if let RunEvent::WindowEvent { label, event: tauri::WindowEvent::Focused(false) | tauri::WindowEvent::Suspended, .. } = &event {
            if label == MAIN_WINDOW_LABEL {
                app.state::<Mutex<crate::ios_install::Startup>>().lock().unwrap().suspended();
            }
        }
        #[cfg(any(mobile, feature = "mobile"))]
        if is_remote_resume_event(&event) {
            #[cfg(target_os = "ios")]
            if !resume_ios_startup(app) { return; }
            resume_remote(app);
        }
        // iOS: queue an opened `bitsov://pair/…` URL for owner review. Never
        // emitted, logged or imported here (pairing_link_ios.rs).
        #[cfg(target_os = "ios")]
        if let RunEvent::Opened { urls } = &event {
            crate::pairing_link_ios::receive(urls.iter().map(|url| url.as_str()));
        }
        // Stop the supervised node on exit — no orphan node with the user's keys.
        //
        // BOTH events are required (app #16). `ExitRequested` fires when the last
        // window closes, which on macOS does NOT quit the app; Cmd-Q goes through
        // NSApplication terminate and emits `Exit`. Matching only `ExitRequested`
        // therefore never ran on macOS: every quit left a mainnet node running with
        // the user's keys loaded, still holding 3141/9735/9736. Reproduced before the
        // fix — the node's ppid went from the GUI's pid to 1 on quit.
        //
        // A repeated shutdown event is a no-op, and a restore in flight can neither
        // hide its old node from this nor start a new one after it (`stop_for_quit`).
        if matches!(event, RunEvent::ExitRequested { .. } | RunEvent::Exit) {
            #[cfg(target_os = "ios")]
            bitsov_ffi::call_audio::terminate();
            let state = app.state::<NodeState>();
            if let Some(proxy) = state.remote_proxy.lock().unwrap().take() {
                proxy.stop();
            }
            #[cfg(all(desktop, not(feature = "mobile")))]
            state.stop_for_quit(NODE_SHUTDOWN_BUDGET);
            #[cfg(any(mobile, feature = "mobile"))]
            state.quitting.store(true, Ordering::SeqCst);
        }
    });
}

/// During deferred iOS cleanup only status reads may enter the app. In
/// particular import/Forget must not write app data that could make the next
/// fresh-install inspection preserve an orphaned identity.
#[cfg(any(target_os = "ios", all(test, unix, desktop, not(feature = "mobile"))))]
fn guard_ios_startup<R: tauri::Runtime>(
    handler: impl Fn(tauri::ipc::Invoke<R>) -> bool + Send + Sync + 'static,
) -> impl Fn(tauri::ipc::Invoke<R>) -> bool + Send + Sync + 'static {
    move |invoke| {
        let webview = invoke.message.webview();
        let startup = webview.state::<Mutex<crate::ios_install::Startup>>();
        let ready = startup.lock().unwrap().ready();
        if !ready && !matches!(invoke.message.command(), "node_status" | "pairing_status") {
            invoke.resolver.reject("Unlock this device and return to BitSov to finish secure setup. If it still fails, restart BitSov.");
            return true;
        }
        handler(invoke)
    }
}

/// Runs synchronously on the event-loop thread, before admitting commands or
/// starting any tasks. Returning false also prevents a duplicate resume task
/// when this foreground event has just started the deferred bootstrap.
#[cfg(target_os = "ios")]
fn resume_ios_startup(app: &AppHandle) -> bool {
    let startup = app.state::<Mutex<crate::ios_install::Startup>>();
    let mut startup = startup.lock().unwrap();
    if startup.ready() { return true; }
    let result = app.path().app_data_dir().map_err(|error| error.to_string()).and_then(|dir| {
        startup.foreground(&dir, bitsov_ffi::client_keychain::app_is_backgrounded(), || bitsov_ffi::client_keychain::delete(&dir.join(PAIRING_STORE_DIR)))
    });
    match result {
        Ok(true) => {
            *app.state::<NodeState>().error.lock().unwrap() = None;
            tauri::async_runtime::spawn(bootstrap_node(app.clone()));
            tauri::async_runtime::spawn(live_bridge(app.clone()));
        }
        Ok(false) => {},
        Err(_) => set_error(&app.state::<NodeState>(), "Secure setup could not finish. Unlock this device and restart BitSov."),
    }
    false
}

/// Normal CS-1 / CS-2 desktop shell: NodeState, wallet commands, bootstrap.
fn app_builder() -> tauri::Builder<tauri::Wry> {
    let builder = tauri::Builder::default();
    #[cfg(all(target_os = "macos", not(feature = "mobile")))]
    let builder = builder.plugin(tauri_plugin_notification::init());
    #[cfg(all(desktop, not(feature = "mobile")))]
    let builder = builder
        // Voice notes and calls: let the webview use the mic/camera without a
        // second in-page prompt. The OS still asks once (Info.plist usage text).
        .on_permission_request(|_webview, kind| match kind {
            tauri::webview::PermissionKind::Microphone | tauri::webview::PermissionKind::Camera => {
                tauri::webview::PermissionResponse::Allow
            }
            _ => tauri::webview::PermissionResponse::Default,
        })
        .plugin(tauri_plugin_shell::init());
    #[cfg(target_os = "android")]
    let builder = builder
        .plugin(device_key::init())
        .plugin(crate::android_network::init())
        .plugin(crate::pairing_link_mobile::init())
        .plugin(crate::phone_recovery::init())
        .plugin(tauri_plugin_barcode_scanner::init());
    // iOS device keys use the statically linked Apple enclave bridge;
    // the QR scanner is the only mobile plugin. Pairing
    // links arrive as `RunEvent::Opened` (see `run`), not through a plugin.
    #[cfg(target_os = "ios")]
    let builder = builder.plugin(tauri_plugin_barcode_scanner::init());
    builder
        .manage(AiState::default())
        .invoke_handler({
            let handler: fn(tauri::ipc::Invoke<tauri::Wry>) -> bool = tauri::generate_handler![
            node_status,
            node_unlock,
            node_unlock_password,
            node_unlock_remember,
            remote_owner_setup,
            local_owner_create,
            local_owner_cancel,
            local_owner_finalize,
            local_owner_reconcile,
            node_repair_initialized,
            node_repair_price_floor,
            fund_state,
            fund_start,
            funding_address,
            payments_balance,
            identity_restore,
            pairing_status,
            trust_acknowledge,
            pairing_retry,
            remote_access_preview,
            remote_access_import,
            remote_access_connect,
            pairing_link_take,
            open_app_settings,
            open_tailscale,
            remote_access_forget,
            node_overview,
            live_link,
            peers_list,
            rooms_list,
            room_members,
            messages_list,
            message_delivery,
            room_thread,
            price_quote,
            first_contact_quote,
            introduction_mine,
            introduction_read,
            introduction_open,
            front_door_mine,
            front_door_read,
            front_door_open,
            front_door_publish,
            front_door_hash_bytes,
            sponsor_status,
            sponsor_offer,
            sponsor_candidate,
            sponsor_owner_approval,
            sponsor_reconcile,
            sponsor_cancel,
            sponsor_request,
            sponsor_request_status,
            first_contact_request,
            first_contact_status,
            first_contact_cancel,
            payments_overview,
            starter_current,
            starter_request,
            energy_read,
            membrane_read,
            spend_status,
            spend_request,
            spend_lock,
            spend_cancel,
            owner_approval_request,
            owner_approval_status,
            owner_approvals_pending,
            owner_approval_approve,
            owner_device_keys,
            add_device,
            join_device,
            device_key_status,
            device_key_register,
            device_key_cancel,
            relation_approve,
            spend_reconcile,
            op_list,
            op_end_call,
            op_repair_call_index,
            op_close_call,
            budget_status,
            budget_approve,
            budget_set,
            budget_pause,
            budget_resume,
            message_send,
            message_retry,
            spend_dismiss_undelivered,
            room_quote,
            invoice_create,
            invoice_amount,
            invoice_status,
            payment_pay,
            payment_keysend,
            invite_create,
            invite_redeem,
            file_price,
            file_send,
            voice_note_fetch,
            file_fetch,
            file_save,
            call_audio_session,
            call_quote,
            call_signal,
            call_status,
            call_block,
            call_hold,
            call_media_open,
            call_media_send,
            call_media_close,
            porch_quote,
            porch_read,
            porch_cards,
            ai_read,
            ai_providers,
            ai_disclose,
            ai_send,
            ai_cancel,
            ai_local_status,
            ai_local_select,
            ai_local_clear
            ];
            #[cfg(target_os = "ios")]
            let handler = guard_ios_startup(handler);
            handler
        })
        .setup(|app| {
            // Install the immutable profile policy before any commands or tasks run.
            crate::profile::install(&app.config().identifier)?;
            app.manage(NodeState::for_identifier(&app.config().identifier));
            #[cfg(all(desktop, not(feature = "mobile")))]
            if assistant_dev_enabled() || assistant_node_enabled() {
                install_assistant_menu(app)?;
            }
            // Install before bootstrap_node reads any pairing secrets.
            #[cfg(all(target_os = "macos", not(feature = "mobile")))]
            bitsov_app::at_rest::install_macos();
            #[cfg(target_os = "ios")]
            {
                let data_dir = app.path().app_data_dir()?;
                bitsov_ffi::client_keychain::exclude_from_backup(&data_dir)?;
                // Installing the sealer reads no identity. Do it only once,
                // before cleanup/marker publication and any deferred bootstrap.
                bitsov_app::at_rest::install_ios()?;
                let mut startup = crate::ios_install::Startup::default();
                // A locked/background launch may have no later suspension event
                // before its first real foreground. Initial active-launch focus
                // events, however, must not consume the retry.
                if bitsov_ffi::client_keychain::app_is_backgrounded() { startup.suspended(); }
                let result = startup.launch(&data_dir, || {
                    bitsov_ffi::client_keychain::delete(&data_dir.join(PAIRING_STORE_DIR))
                });
                let retry_pending = startup.retry_pending();
                app.manage(Mutex::new(startup));
                if let Err(error) = result {
                    if !retry_pending { return Err(error.into()); }
                    set_error(&app.state::<NodeState>(), "Unlock this device and return to BitSov to finish secure setup.");
                    return Ok(());
                }
            }
            #[cfg(target_os = "android")]
            bitsov_app::at_rest::install(Arc::new(device_key::KeystoreSealer))?;
            let handle = app.handle().clone();
            tauri::async_runtime::spawn(bootstrap_node(handle));
            tauri::async_runtime::spawn(live_bridge(app.handle().clone()));
            Ok(())
        })
}

/// Sealed assistant only: mock rows, no node, no wallet, no network client.
///
/// Compiled only for debug + `sit-mock`. Entered from `main` when
/// `BITSOV_ASSISTANT=1`. Must not touch NodeState, bootstrap_node, the shell
/// sidecar plugin, or privileged invoke handlers.
#[cfg(all(debug_assertions, feature = "sit-mock"))]
#[cfg(all(desktop, not(feature = "mobile")))]
fn assistant_mock_builder() -> tauri::Builder<tauri::Wry> {
    tauri::Builder::default()
        .invoke_handler(tauri::generate_handler![])
        .setup(|app| {
            // Open the sealed window first so closing the config main window
            // does not leave the process with zero windows.
            let source = Feed::mock(MockReason::NotPaired).init_script();
            open_assistant_window(app.handle(), source).map_err(
                |e| -> Box<dyn std::error::Error> { e.into() },
            )?;
            if let Some(main) = app.get_webview_window(MAIN_WINDOW_LABEL) {
                let _ = main.close();
            }
            Ok(())
        })
}

#[cfg(all(test, desktop, not(feature = "mobile")))]
mod remote_test_profile_tests {
    use super::*;

    #[test]
    fn remote_test_is_unpaired_remote_and_refuses_local_processes() {
        let state = NodeState::for_identifier("tech.mindlink.bitsov.remotetest");
        assert!(state.pairing_snapshot().remote);
        assert!(state.require_local_node().is_err());
        // A missing command would give a spawn error if the profile guard were lost.
        let error = state.spawn_child(&mut std::process::Command::new("/no-such-node"))
            .unwrap_err();
        assert!(error.contains("remote pairing only"), "{error}");
        assert!(state.child.lock().unwrap().is_none());
        assert!(state.config.lock().unwrap().is_none());
    }

    #[test]
    fn other_profiles_keep_the_local_node_path() {
        for identifier in ["tech.mindlink.bitsov", "tech.mindlink.bitsov.devexternal"] {
            let state = NodeState::for_identifier(identifier);
            assert!(!state.pairing_snapshot().remote);
            assert!(state.require_local_node().is_ok());
        }
    }
}

/// Loopback mock harness shared with `tests/pairing.rs` (ephemeral port, test keys).
#[cfg(all(test, desktop, not(feature = "mobile")))]
#[allow(dead_code)]
#[path = "../tests/support/mod.rs"]
mod test_support;

#[cfg(test)]
mod device_sign_error_tests {
    use super::*;

    #[test]
    fn repeated_status_reads_use_only_metadata_even_when_protected_bytes_are_unreadable() {
        let dir = tempfile::tempdir().unwrap();
        let state = NodeState::for_identifier("tech.mindlink.bitsov");
        let record = device::Record { public_key: "04".into(), registered: true, ..Default::default() };
        device::save_record(dir.path(), &record).unwrap();
        let marker = dir.path().join("device-key.keychain");
        std::fs::write(&marker, b"public marker").unwrap();
        let blob = dir.path().join(device::BLOB_FILE);
        std::fs::write(&blob, b"not a readable enclave key").unwrap();
        #[cfg(unix)] {
            use std::os::unix::fs::PermissionsExt;
            std::fs::set_permissions(&blob, std::fs::Permissions::from_mode(0)).unwrap();
            std::fs::set_permissions(&marker, std::fs::Permissions::from_mode(0)).unwrap();
        }
        for _ in 0..20 {
            assert_eq!(local_device_record(&state, dir.path()).unwrap(), Some(record.clone()));
        }
        assert_eq!(device::load_record(dir.path()), Some(record));
        assert!(blob.exists() && marker.exists());
    }

    #[test]
    fn local_key_waits_for_registration_before_cleaning_a_missing_blob() {
        let state = Arc::new(NodeState::for_api("http://127.0.0.1:1/api/v1"));
        let dir = tempfile::tempdir().unwrap();
        device::save_record(dir.path(), &device::Record::default()).unwrap();
        let guard = state.device_lifecycle.lock().unwrap();
        let reader_state = Arc::clone(&state);
        let store = dir.path().to_path_buf();
        let (started_tx, started_rx) = std::sync::mpsc::channel();
        let (done_tx, done_rx) = std::sync::mpsc::channel();
        let reader = std::thread::spawn(move || {
            started_tx.send(()).unwrap();
            let result = local_key_with(&reader_state, &store, |_| Ok([4; 65]));
            done_tx.send(()).unwrap();
            result
        });
        started_rx.recv().unwrap();
        let early = done_rx.recv_timeout(Duration::from_millis(100));
        let blob = b"new wrapped key";
        let record = device::Record { public_key: hex::encode([4; 65]), registered: true, ..Default::default() };
        device::save_blob(dir.path(), blob).unwrap();
        device::save_record(dir.path(), &record).unwrap();
        drop(guard);
        let result = reader.join().unwrap().unwrap();
        assert!(matches!(early, Err(std::sync::mpsc::RecvTimeoutError::Timeout)),
            "key reads must wait for registration to finish publishing");
        assert_eq!(result, Some((blob.to_vec(), record.clone())));
        assert_eq!(device::load_blob(dir.path()).as_deref(), Some(blob.as_slice()));
        assert_eq!(device::load_record(dir.path()), Some(record));
    }

    #[test]
    fn local_key_removes_the_stale_record_when_the_blob_is_missing() {
        let dir = tempfile::tempdir().unwrap();
        let record = device::Record { registered: true, ..Default::default() };
        device::save_record(dir.path(), &record).unwrap();
        assert!(local_key_with(&NodeState::for_api("http://127.0.0.1:1/api/v1"), dir.path(), |_| panic!("missing blob must not reach the bridge"))
            .unwrap().is_none());
        assert!(!dir.path().join(device::RECORD_FILE).exists());
        assert!(!dir.path().join(device::BLOB_FILE).exists());
    }

    #[test]
    fn local_key_recovers_a_blob_published_before_its_public_record() {
        let dir = tempfile::tempdir().unwrap();
        device::save_blob(dir.path(), b"synthetic interrupted enrollment").unwrap();
        let state = NodeState::for_api("http://127.0.0.1:1/api/v1");
        let public = [4; device_key::PUBLIC_KEY_LEN];
        let (blob, record) = local_key_with(&state, dir.path(), |_| Ok(public)).unwrap().unwrap();
        assert_eq!(blob, b"synthetic interrupted enrollment");
        assert_eq!(record.public_key, hex::encode(public));
        assert!(!record.registered);
        assert_eq!(device::load_record(dir.path()), Some(record));
    }

    #[cfg(unix)]
    #[test]
    fn local_key_preserves_the_record_and_blob_on_a_private_file_read_error() {
        use std::os::unix::fs::PermissionsExt;
        let dir = tempfile::tempdir().unwrap();
        let record = device::Record { registered: true, ..Default::default() };
        let blob = b"synthetic wrapped key";
        device::save_record(dir.path(), &record).unwrap();
        device::save_blob(dir.path(), blob).unwrap();
        let path = dir.path().join(device::BLOB_FILE);
        std::fs::set_permissions(&path, std::fs::Permissions::from_mode(0o644)).unwrap();
        assert!(device::read_private(&path).is_err());
        assert_eq!(local_key_with(&NodeState::for_api("http://127.0.0.1:1/api/v1"), dir.path(), |_| panic!("unreadable blob must not reach the bridge"))
            .unwrap_err().code, "device_key");
        assert_eq!(device::load_record(dir.path()), Some(record));
        assert_eq!(std::fs::read(path).unwrap(), blob);
    }

    #[test]
    fn local_key_preserves_transport_failures_but_forgets_invalid_or_mismatched_keys() {
        use device_key::DeviceKeyError::*;
        for public in [Err(Other(-6)), Err(Unavailable), Err(Cancelled), Err(BiometryUnavailable),
            Err(Invalid), Ok([5; 65]), Ok([4; 65])] {
            let dir = tempfile::tempdir().unwrap();
            let blob = b"synthetic wrapped key";
            let record = device::Record { public_key: hex::encode([4; 65]), registered: true, ..Default::default() };
            device::save_blob(dir.path(), blob).unwrap();
            device::save_record(dir.path(), &record).unwrap();
            let result = local_key_with(&NodeState::for_api("http://127.0.0.1:1/api/v1"), dir.path(), |_| public);
            match public {
                value if value == Err(Invalid) || value == Ok([5; 65]) => {
                    assert!(result.unwrap().is_none());
                    assert!(device::load_blob(dir.path()).is_none());
                    assert!(device::load_record(dir.path()).is_none());
                }
                _ => {
                    assert_eq!(device::load_blob(dir.path()).as_deref(), Some(blob.as_slice()));
                    assert_eq!(device::load_record(dir.path()), Some(record));
                    if public.is_err() { assert!(result.is_err(), "transient failure must not offer key creation"); }
                    else { assert!(result.unwrap().is_some()); }
                }
            }
        }
    }

    #[test]
    fn malformed_signature_transport_error_does_not_forget_key_or_registration() {
        let dir = tempfile::tempdir().unwrap();
        let blob = b"synthetic wrapped enclave key";
        let record = device::Record {
            public_key: "04".into(), key_id: Some("registered-key".into()),
            registered: true, ..Default::default()
        };
        device::save_blob(dir.path(), blob).unwrap();
        device::save_record(dir.path(), &record).unwrap();
        // The ABI contract tests pin malformed signature output to Other(-6).
        // Exercise the real app mapping and deletion handler shared by relation
        // approval and home unlock, with on-disk key and enrollment state.
        let error = device_error(device_key::DeviceKeyError::Other(-6));
        assert_eq!(error.code, "device_key");
        assert!(!forget_invalid_signing_key(dir.path(), &error));
        assert_eq!(device::load_blob(dir.path()).as_deref(), Some(blob.as_slice()));
        assert_eq!(device::load_record(dir.path()), Some(record));

        // A genuine native invalidation must still require re-enrollment.
        let error = device_error(device_key::DeviceKeyError::Invalid);
        assert!(forget_invalid_signing_key(dir.path(), &error));
        assert!(device::load_blob(dir.path()).is_none());
        assert!(device::load_record(dir.path()).is_none());
    }

    #[cfg(unix)]
    #[test]
    fn cancelled_protected_read_and_signature_preserve_the_enrolled_identity() {
        for during_read in [true, false] {
            let dir = tempfile::tempdir().unwrap();
            let blob = b"synthetic wrapped enclave key";
            let record = device::Record { registered: true, key_id: Some("registered-key".into()), ..Default::default() };
            device::save_blob(dir.path(), blob).unwrap();
            device::save_record(dir.path(), &record).unwrap();
            for name in ["device-key.keychain", "device-key.public"] {
                std::fs::write(dir.path().join(name), b"public metadata").unwrap();
            }
            let error = stored_signing_operation(dir.path(), || {
                if during_read { Err(crate::apple_key_material::ReadError::Cancelled) }
                else { Ok(Some(zeroize::Zeroizing::new(blob.to_vec()))) }
            }, |loaded| {
                assert!(!during_read, "a cancelled read must never reach signing");
                assert_eq!(loaded, blob);
                Err(device_key::DeviceKeyError::Cancelled)
            }).unwrap_err();
            assert_eq!(error.code, "device_cancelled");
            assert_eq!(device::load_blob(dir.path()).as_deref(), Some(blob.as_slice()));
            assert_eq!(device::load_record(dir.path()), Some(record));
            for name in ["device-key.keychain", "device-key.public"] {
                assert_eq!(std::fs::read(dir.path().join(name)).unwrap(), b"public metadata");
            }
        }
    }
}

#[cfg(test)]
mod trust_tests {
    use super::*;

    #[test]
    fn trust_is_bound_to_the_ready_authenticated_node_and_survives_reopening() {
        let dir = tempfile::tempdir().unwrap();
        let state = NodeState::for_api("http://127.0.0.1:1/api/v1");
        *state.app_dir.lock().unwrap() = Some(dir.path().to_path_buf());
        *state.node_id.lock().unwrap() = Some("abcd".into());
        state.remote_mode.store(true, Ordering::SeqCst);
        assert!(state.acknowledge_trust("abcd", true, false).is_err());
        *state.ready.lock().unwrap() = true;
        state.pairing_view.lock().unwrap().state = "paired";
        assert!(state.pairing_snapshot().trust_acknowledged_node_id.is_none());
        assert!(state.acknowledge_trust("cdef", true, false).is_err());
        assert!(state.acknowledge_trust("abcd", false, false).is_err());
        state.pairing_view.lock().unwrap().bootstrap = Some("bootstrap".into());
        assert!(state.acknowledge_trust("abcd", true, false).is_err());
        state.pairing_view.lock().unwrap().bootstrap = None;
        assert!(state.acknowledge_trust("ABCD", true, false).unwrap());
        drop(state);

        let reopened = NodeState::for_api("http://127.0.0.1:1/api/v1");
        *reopened.app_dir.lock().unwrap() = Some(dir.path().to_path_buf());
        *reopened.node_id.lock().unwrap() = Some("abcd".into());
        reopened.remote_mode.store(true, Ordering::SeqCst);
        assert_eq!(reopened.pairing_snapshot().trust_acknowledged_node_id.as_deref(), Some("abcd"));
        *reopened.node_id.lock().unwrap() = Some("cdef".into());
        assert!(reopened.pairing_snapshot().trust_acknowledged_node_id.is_none());
    }
}

