    /// Genome #100's BUG-PSI reply: admission settled, the session did not form.
    fn psi_502(amount: u64, prior: u64, current: u64, tail: &str) -> (u16, String) {
        (502, serde_json::json!({
            "error": format!("payment settled but send did not complete (prior admission: {prior} msat; current call: {current} msat): {tail}"),
            "code": "payment_settled_send_incomplete",
            "amount_msat": amount,
        }).to_string())
    }
    const PSI_TIMEOUT: &str = "internal error: first-contact admission payment settled and a signed proof is held, but the E2EE session did not establish within 25s — retry the message shortly; the retry is guarded by admission idempotence and will NOT pay admission again";

    /// The spend journal's record as the node sees it at each compose, so a
    /// test can prove the record was never absent while a retry was sent.
    type AtCompose = Arc<Mutex<Vec<Option<serde_json::Value>>>>;

    /// Compose answers from `replies` in order; everything else is `happy()`.
    fn compose_script(replies: Vec<(u16, String)>) -> Routes {
        compose_watch(replies).0
    }

    fn compose_watch(replies: Vec<(u16, String)>) -> (Routes, Arc<Mutex<Option<PathBuf>>>, AtCompose) {
        let next = Arc::new(Mutex::new(replies.into_iter()));
        let journal: Arc<Mutex<Option<PathBuf>>> = Arc::new(Mutex::new(None));
        let seen: AtCompose = Arc::new(Mutex::new(Vec::new()));
        let (j, s) = (journal.clone(), seen.clone());
        let routes: Routes = Arc::new(move |m: &str, p: &str, b: &str| {
            if p != "/messages/compose" { return happy()(m, p, b); }
            if let Some(path) = j.lock().unwrap().clone() {
                s.lock().unwrap().push(std::fs::read(path).ok().map(|bytes| serde_json::from_slice(&bytes).unwrap()));
            }
            next.lock().unwrap().next().expect("no further compose expected")
        });
        (routes, journal, seen)
    }

    fn journal_file(node: &Fake) -> PathBuf {
        node._dir.path().join("app-spend").join("spend-pending.json")
    }

    fn compose_bodies(node: &Fake) -> Vec<serde_json::Value> {
        node.posts().into_iter().filter(|(p, _)| p == "/messages/compose").map(|(_, b)| b).collect()
    }

    fn delivered(id: &str, amount: u64) -> (u16, String) {
        (200, serde_json::json!({"message_id": id, "delivered": true, "amount_msat": amount, "max_routing_fee_msat": 0}).to_string())
    }

    fn pending(node: &Fake) -> Option<spend_journal::Pending> {
        spend_journal(&node.state).unwrap().pending().unwrap()
    }

    fn book(node: &Fake) -> Vec<(String, u64, bool)> {
        with_book(&node.state, false, |b| Ok(b.ledger.iter().map(|e| (e.id.clone(), e.msat, e.settled)).collect())).unwrap()
    }

    /// A first send whose admission settled and whose message did not go.
    async fn psi_first(node: &Fake) -> spend_journal::Pending {
        spend_advance(&node.state, true).await.unwrap();
        let err = do_message_send(&node.state, A, false, "gm", 14000, None).await.unwrap_err();
        assert_eq!(err.code, "payment_settled_undelivered", "{}", err.message);
        pending(node).expect("the fence stays")
    }

    // ---- exactly-once slice 3: operation_id journal and reconcile ----------------

    /// Genome `message_operations_v1`, reduced to what the app relies on: one
    /// operation per id, paid at most once, 409 on changed text, and
    /// `GET /messages/operations/{id}`. `pays` counts Lightning dispatches.
    #[derive(Default)]
    struct OpsNode {
        ops: std::collections::HashMap<String, (String, &'static str)>,
        pays: usize,
        /// Next new operation: the state it ends in, and whether its reply is lost.
        script: Vec<(&'static str, bool)>,
        /// Answer a paid operation's first POST with the node's 502 (paid, not sent).
        settled_incomplete: bool,
        /// Record nothing for the next POST and lose its reply (never reached the handler).
        drop_next: bool,
        /// The peer asks for admission again (reconnect/restart) and the node
        /// refuses to pay it under the cap, as genome `readmit_then_pay` does.
        readmission_capped: bool,
        /// Refusals answered so far: the first carries genome's `reason`, the
        /// next an older node's wording only.
        readmission_refusals: usize,
    }

    /// Genome's refusal of a capped reconnect re-admission with its stable
    /// `reason` (the wording deliberately not the older nodes').
    fn readmission_coded_reply() -> (u16, String) {
        (409, serde_json::json!({"code": "price_cap_exceeded", "reason": "readmission_required",
            "error": format!("{A} needs a paid admission on this connection; nothing was paid.")}).to_string())
    }

    /// An older genome's refusal of a capped reconnect re-admission (compose.rs
    /// `readmit_then_pay` before the reason code): English wording only.
    fn readmission_capped_reply() -> (u16, String) {
        (409, serde_json::json!({"code": "price_cap_exceeded", "error": format!(
            "{A} requires admission again on a new connection, and the confirmed cap covers the message only; \
             no invoice was paid. Send without a cap to pay admission.")}).to_string())
    }

    const OP_HASH: &str = "abababababababababababababababababababababababababababababababab";

    fn op_reply(id: &str, state: &str) -> String {
        let unpaid = matches!(state, "prepared" | "released" | "abandoned");
        serde_json::json!({"operation_id": id, "state": state, "accepted": state == "acked", "payment_hash": if unpaid { None } else { Some(OP_HASH) },
            "retry_allowed": matches!(state, "prepared" | "released" | "paid" | "sent" | "rejected_retryable"),
            "max_routing_fee_msat": 0, "message_id": "m1", "delivered": matches!(state, "sent" | "acked"), "amount_msat": if unpaid { 0 } else { 2000 }}).to_string()
    }

    fn ops_node() -> (Routes, Arc<Mutex<OpsNode>>) {
        let node = Arc::new(Mutex::new(OpsNode::default()));
        let n = node.clone();
        let routes: Routes = Arc::new(move |m: &str, p: &str, b: &str| {
            if p == "/status" {
                return (200, serde_json::json!({"api_capabilities": ["paid_send_caps_v1", "room_terminal_outcomes_v1", "message_operations_v1"]}).to_string());
            }
            if let Some(id) = p.strip_prefix("/messages/operations/") {
                return match n.lock().unwrap().ops.get(id) {
                    Some((_, state)) => (200, op_reply(id, state)),
                    None => (404, r#"{"error":"operation not found","code":404}"#.into()),
                };
            }
            if p != "/messages/compose" { return happy()(m, p, b); }
            let body: serde_json::Value = serde_json::from_str(b).unwrap();
            let Some(id) = body["operation_id"].as_str().map(str::to_string) else { return happy()(m, p, b); };
            let text = body["plaintext"].as_str().unwrap().to_string();
            let mut node = n.lock().unwrap();
            if std::mem::take(&mut node.drop_next) {
                drop(node);
                std::thread::sleep(Duration::from_millis(150));
                return (500, "{}".into());
            }
            let lost = match node.ops.get(&id).cloned() {
                Some((known, _)) if known != text => {
                    return (409, serde_json::json!({"error": "operation_mismatch", "code": "operation_mismatch", "operation_id": id,
                        "state": "prepared", "payment_hash": null, "accepted": false, "retry_allowed": true}).to_string());
                }
                // Paid already: re-send it, pay nothing. Unresolved: refuse.
                Some((_, "paid" | "sent" | "rejected_retryable")) => { node.ops.insert(id.clone(), (text, "acked")); false }
                Some((_, "acked")) => false,
                Some((_, "paying" | "payment_unknown")) => {
                    return (409, serde_json::json!({"error": "payment_unresolved", "code": "payment_unresolved", "operation_id": id,
                        "state": "payment_unknown", "payment_hash": OP_HASH, "accepted": false, "retry_allowed": false}).to_string());
                }
                _ if node.readmission_capped => {
                    node.ops.insert(id.clone(), (text, "released"));
                    node.readmission_refusals += 1;
                    return if node.readmission_refusals == 1 { readmission_coded_reply() } else { readmission_capped_reply() };
                }
                _ => {
                    let (state, lost) = if node.script.is_empty() { ("acked", false) } else { node.script.remove(0) };
                    if !matches!(state, "prepared" | "released") { node.pays += 1; }
                    node.ops.insert(id.clone(), (text, state));
                    if state == "paid" && node.settled_incomplete {
                        return (502, serde_json::json!({"error": "payment settled but send did not complete", "code": "payment_settled_send_incomplete",
                            "amount_msat": 2000, "operation_id": id, "state": "paid", "payment_hash": OP_HASH, "accepted": false, "retry_allowed": true}).to_string());
                    }
                    lost
                }
            };
            let state = node.ops[&id].1;
            drop(node);
            if lost { std::thread::sleep(Duration::from_millis(150)); }
            (200, op_reply(&id, state))
        });
        (routes, node)
    }

    /// A node that loses replies after `spend_timeout`, as a crash after the POST would.
    fn ops_fake(configure: impl FnOnce(&mut OpsNode)) -> (Fake, Arc<Mutex<OpsNode>>) {
        let (routes, ops) = ops_node();
        configure(&mut ops.lock().unwrap());
        let mut node = fake(AuthMode::Local, routes);
        node.state.spend_timeout = Duration::from_millis(60);
        (node, ops)
    }

    fn op_ids(node: &Fake) -> Vec<Option<String>> {
        compose_bodies(node).iter().map(|b| b["operation_id"].as_str().map(str::to_string)).collect()
    }

    fn gets(node: &Fake) -> Vec<String> {
        node.targets().into_iter().filter(|t| t.starts_with("GET /messages/operations/")).collect()
    }

    #[tokio::test]
    async fn delivery_lookup_is_read_only_and_requires_matching_node_evidence() {
        let id = "12345678-1234-4234-8234-123456789abc";
        for status in ["sent", "paid", "acked", "failed_paid", "unknown"] {
            let routes: Routes = Arc::new(move |method, path, _| {
                assert_eq!(method, "GET");
                assert_eq!(path, format!("/messages/operations/{id}"));
                (200, serde_json::json!({"operation_id":id, "message_id":A, "state":status,
                    "accepted":status == "acked", "delivered":true, "amount_msat":1000,
                    "payment_hash":"never-forward-this"}).to_string())
            });
            let node = fake(AuthMode::Local, routes);
            let event = read_message_delivery(&node.state, id, A).await.unwrap();
            match status {
                "acked" => assert!(matches!(event, Some(control::LiveEvent::Delivery { status, .. }) if status == "delivered")),
                "failed_paid" => assert!(matches!(event, Some(control::LiveEvent::Delivery { status, .. }) if status == "rejected")),
                _ => assert!(event.is_none(), "transport/payment success is not recipient delivery"),
            }
            assert_eq!(node.targets(), [format!("GET /messages/operations/{id}")]);
        }
        for (operation, message) in [("another-operation", A), (id, C)] {
            let routes: Routes = Arc::new(move |_, _, _| (200, serde_json::json!({
                "operation_id":operation, "message_id":message, "state":"acked", "accepted":true,
                "delivered":true, "amount_msat":1000}).to_string()));
            let node = fake(AuthMode::Local, routes);
            assert!(read_message_delivery(&node.state, id, A).await.is_err());
        }
        let node = fake(AuthMode::Local, Arc::new(|_, _, _| panic!("invalid ID must not reach the node")));
        assert!(read_message_delivery(&node.state, "../other?x", A).await.is_err());
        assert!(read_message_delivery(&node.state, id, "invalid-message").await.is_err());
    }

    #[tokio::test]
    async fn operation_id_is_journaled_before_the_first_post_and_accepted_is_reported() {
        let (routes, ops) = ops_node();
        let seen: Arc<Mutex<Vec<Option<serde_json::Value>>>> = Arc::new(Mutex::new(Vec::new()));
        let journal: Arc<Mutex<Option<PathBuf>>> = Arc::new(Mutex::new(None));
        let (s, j) = (seen.clone(), journal.clone());
        let watched: Routes = Arc::new(move |m, p, b| {
            if p == "/messages/compose" {
                let path = j.lock().unwrap().clone().unwrap();
                let body: serde_json::Value = serde_json::from_str(b).unwrap();
                let id = body["operation_id"].as_str().unwrap();
                let record: serde_json::Value = serde_json::from_slice(&std::fs::read(
                    path.parent().unwrap().join("ops").join(format!("{id}.json"))).unwrap()).unwrap();
                assert_eq!(record["state"], "dispatching", "ledger durable before POST");
                assert_eq!(record["op_id"], id);
                s.lock().unwrap().push(std::fs::read(path).ok().map(|bytes| serde_json::from_slice(&bytes).unwrap()));
            }
            routes(m, p, b)
        });
        let node = fake(AuthMode::Local, watched);
        *journal.lock().unwrap() = Some(journal_file(&node));
        spend_advance(&node.state, true).await.unwrap();
        let receipt = do_message_send(&node.state, A, false, "gm", 14000, None).await.unwrap();
        let ids = op_ids(&node);
        let id = ids[0].clone().expect("a 1:1 compose carries an operation_id");
        assert!(uuid_v4(&id), "{id}");
        let at_post = seen.lock().unwrap()[0].clone().expect("journal on disk before the POST");
        assert!(at_post["dispatched_at"].as_u64().is_some_and(|t| t > 0 && t <= spend_journal::timestamp_ms()), "dispatch time is durable before the POST");
        assert_eq!(at_post["operation_id"], id.as_str());
        assert!(!at_post.to_string().contains("\"gm\""), "no plaintext in the journal");
        assert_eq!((receipt.accepted, receipt.state.as_deref(), receipt.operation_id.as_deref()), (true, Some("acked"), Some(id.as_str())));
        assert!(pending(&node).is_none());
        assert_eq!(ops.lock().unwrap().pays, 1);
        // A second, separate send is a separate operation.
        do_message_send(&node.state, A, false, "gm", 14000, None).await.unwrap();
        let ids = op_ids(&node);
        assert_ne!(ids[0], ids[1]);
    }

    fn ledger_record(node: &Fake, id: &str) -> serde_json::Value {
        let path = journal_file(node).parent().unwrap().join("ops").join(format!("{id}.json"));
        serde_json::from_slice(&std::fs::read(path).expect("durable operation record")).unwrap()
    }

    #[tokio::test]
    async fn ledger_records_existing_outcomes_without_changing_the_fence() {
        for (status, body, code, state, held) in [
            (400, r#"{"code":"not_dispatched"}"#, "not_dispatched", "unpaid", false),
            (401, "{}", "spend_refused", "unpaid", false),
            (403, "{}", "spend_refused", "unpaid", false),
            (503, r#"{"code":"not_ready","money_ready":false}"#, "not_ready", "unpaid", false),
            (409, r#"{"code":"price_cap_exceeded"}"#, "price_cap_exceeded", "unpaid", false),
            (409, r#"{"code":"operation_mismatch"}"#, "operation_mismatch", "unpaid", false),
            (409, r#"{"code":"budget_exceeded","reason":"per_call"}"#, "grant_per_call", "unpaid", false),
            (409, r#"{"code":"failed_paid"}"#, "failed_paid", "failed_paid", false),
            (409, r#"{"code":"payment_unresolved"}"#, "payment_unknown", "unknown", true),
            (500, "{}", "spend_unknown", "unknown", true),
            (200, "broken", "spend_unknown", "unknown", true),
            // A call-rules refusal is proven unpaid only for a call signal.
            (400, r#"{"reason":"call_not_live"}"#, "call_not_live", "unpaid", false),
        ] {
            let (inner, _) = ops_node();
            let calls = call_routes(Some(10000));
            let node = fake(AuthMode::Local, Arc::new(move |m, p, b| {
                if p == "/messages/compose" { (status, body.into()) }
                else if p == "/status" { inner(m, p, b) }
                else { calls(m, p, b) }
            }));
            spend_advance(&node.state, true).await.unwrap();
            let err = if code == "call_not_live" {
                do_call_signal(&node.state, A, 403, OFFER, 14000).await.unwrap_err()
            } else {
                do_message_send(&node.state, A, false, "PRIVATE", 14000, None).await.unwrap_err()
            };
            if !matches!(status, 401 | 403) { assert_eq!(err.code, code, "{body}"); }
            let id = op_ids(&node)[0].clone().unwrap();
            assert_eq!(serde_json::to_value(&err).unwrap()["operation_id"], id);
            let record = ledger_record(&node, &id);
            assert_eq!(record["state"], state, "{body}");
            assert!(!record.to_string().contains("PRIVATE"));
            assert_eq!(pending(&node).is_some(), held, "existing single-slot fence: {body}");
            assert_eq!(ledger_record(&node, &id), record, "record is retained");
        }
    }

    #[tokio::test]
    async fn call_rules_refusals_release_budget_and_record_unpaid() {
        for reason in ["call_id_used", "call_busy", "call_signal_in_flight", "call_signal_invalid", "call_not_live"] {
            for kind in 400..=403 {
                let (ops, _) = ops_node();
                let calls = call_routes(Some(10000));
                let node = fake(AuthMode::Local, Arc::new(move |m, p, b| {
                    if p == "/messages/compose" { (400, serde_json::json!({"reason": reason}).to_string()) }
                    else if p == "/status" { ops(m, p, b) }
                    else { calls(m, p, b) }
                }));
                do_budget_approve(&node.state, 500000, budget::PresetId::Careful).await.unwrap();
                with_book(&node.state, true, |b| b.set_limit(A, false, 50000)).unwrap();
                let err = do_call_signal(&node.state, A, kind, OFFER, 15000).await.unwrap_err();
                assert_eq!(err.code, reason, "kind {kind}");
                assert_eq!(err.message, "The node refused this call signal before payment. Nothing was paid.");
                let id = op_ids(&node)[0].clone().unwrap();
                assert_eq!(err.operation_id.as_deref(), Some(id.as_str()));
                let record = ledger_record(&node, &id);
                assert_eq!(record["state"], "unpaid");
                assert_eq!(record["paid_msat"], 0);
                assert!(record["settled_ms"].as_u64().is_some());
                assert!(pending(&node).is_none());
                assert!(book(&node).is_empty(), "reservation released");
                assert_eq!(budget_now(&node.state).unsettled_msat, 0);
                assert_eq!(budget_now(&node.state).spent_msat, 0);
            }
        }
    }

    #[tokio::test]
    async fn call_rules_refusals_outside_proven_scope_stay_unknown() {
        for (path, room, kind, status, reply) in [
            ("/messages/compose", false, 200, 400, r#"{"reason":"call_not_live"}"#),
            ("/messages/compose", true, 403, 400, r#"{"reason":"call_not_live"}"#),
            ("/messages/compose", false, 403, 409, r#"{"reason":"call_not_live"}"#),
            ("/messages/compose", false, 403, 400, r#"{"reason":"call_price_unknown"}"#),
            ("/messages/compose", false, 399, 400, r#"{"reason":"call_not_live"}"#),
            ("/messages/compose", false, 404, 400, r#"{"reason":"call_not_live"}"#),
            ("/payments/keysend", false, 403, 400, r#"{"reason":"call_not_live"}"#),
            ("/messages/compose", false, 403, 400, r#"{"code":"call_not_live"}"#),
            ("/messages/compose", false, 403, 400, "broken"),
        ] {
            let node = fake(AuthMode::Local, Arc::new(move |m, p, b| {
                if p == path { (status, reply.into()) } else { happy()(m, p, b) }
            }));
            spend_advance(&node.state, true).await.unwrap();
            let charge = Charge { target: A.into(), room, confirm: None, readmission_possible: false,
                confirmed: false, operation: true, envelope_ids: Some(true) };
            let err = money_post_with(&node.state, Auth::Window(approval_generation(&node.state).unwrap()), path,
                serde_json::json!({"recipient": A, "is_room": room, "kind": kind, "plaintext": OFFER}),
                15000, Some(charge), None).await.unwrap_err();
            assert_eq!(err.code, "spend_unknown", "{path} {room} {kind} {status} {reply}");
            let held = pending(&node).expect("single slot remains held");
            if let Some(id) = held.operation_id.as_ref() {
                assert_eq!(ledger_record(&node, id)["state"], "unknown");
                assert_eq!(err.operation_id.as_ref(), Some(id));
            }
            assert!(budget_now(&node.state).unsettled_msat > 0);
            assert_eq!(no_pending_spend(&node.state).unwrap_err().code, "spend_unknown");
        }
    }

    #[tokio::test]
    async fn call_rules_refusals_existing_attempts_stay_unknown() {
        // An answer exercises the #278 guard independently of the offer admission fence.
        // A resumable resend reuses an id whose earlier payment may still be
        // unresolved. A delivery retry retains its earlier payment, even on
        // legacy nodes without operation ids. Neither refusal proves unpaid.
        for kind in [400, 401] {
        for (delivery_retry, has_operation_id) in [(false, true), (true, true), (true, false)] {
            let node = fake(AuthMode::Local, Arc::new(move |m, p, b| {
                if p == "/messages/compose" { (400, r#"{"reason":"call_id_used"}"#.into()) }
                else { happy()(m, p, b) }
            }));
            spend_advance(&node.state, true).await.unwrap();
            let body = serde_json::json!({"recipient": A, "is_room": false, "kind": kind, "plaintext": OFFER});
            let op = spend_journal::operation(&body);
            let id = has_operation_id.then(|| spend_journal::new_operation_id().unwrap());
            let journal = spend_journal(&node.state).unwrap();
            let mut prior = journal.begin_operation(OWN, "/messages/compose", &body, 15000,
                id.clone().map(|id| (id, op.clone()))).unwrap();
            prior.resumable = !delivery_retry;
            if delivery_retry {
                prior.accounting_msat = Some(2000);
                prior.undelivered = Some(spend_journal::Undelivered {
                    peer: A.into(), paid_msat: 2000, retry: true, op,
                    admission_msat: 2000, in_flight: false, attempts: 0, payment_hash: None,
                });
                with_book(&node.state, true, |b| {
                    b.reserve(&prior.request_hash, A, false, 15000, now_ms());
                    b.settle(&prior.request_hash, 2000, now_ms());
                    Ok(())
                }).unwrap();
            }
            journal.save(&prior).unwrap();
            drop(journal);
            let charge = Charge { target: A.into(), room: false, confirm: None, readmission_possible: false,
                confirmed: false, operation: has_operation_id, envelope_ids: Some(true) };
            let err = money_post_with(&node.state, Auth::Window(approval_generation(&node.state).unwrap()),
                "/messages/compose", body, 15000, Some(charge), prior.undelivered.as_ref()).await.unwrap_err();
            if has_operation_id && (kind == 400 || !delivery_retry) {
                assert_eq!(err.code, if kind == 400 { "call_admission_open" } else { "spend_unknown" });
                assert!(op_ids(&node).is_empty(), "the call fence rejects before retry dispatch");
                assert_eq!(pending(&node).unwrap().operation_id, id);
                continue;
            }
            assert_eq!(op_ids(&node), [id.clone()], "the existing operation id is reused");
            assert_eq!(err.code, "spend_unknown", "retry={delivery_retry}, operation_id={has_operation_id}");
            assert!(!err.message.contains("Nothing was paid"));
            assert_eq!(err.operation_id, id);
            let held = pending(&node).expect("single slot remains held");
            assert_eq!(held.operation_id, id);
            assert!(!held.resumable);
            if let Some(id) = id.as_ref() {
                assert_eq!(ledger_record(&node, id)["state"], "unknown");
            }
            if delivery_retry {
                let undelivered = held.undelivered.unwrap();
                assert!(undelivered.in_flight);
                assert_eq!(undelivered.paid_msat, 2000);
                assert!(book(&node).contains(&(prior.request_hash.clone(), 2000, true)), "original payment retained");
            }
            assert!(budget_now(&node.state).unsettled_msat > 0);
            assert_eq!(no_pending_spend(&node.state).unwrap_err().code, "spend_unknown");
        }
        }
    }

    #[tokio::test]
    async fn expired_hangup_refusal_allows_next_keysend() {
        let (ops, _) = ops_node();
        let calls = call_routes(Some(10000));
        let node = fake(AuthMode::Local, Arc::new(move |m, p, b| {
            if p == "/messages/compose" && serde_json::from_str::<serde_json::Value>(b).unwrap()["kind"] == 403 {
                // The node has expired the call: hangup is refused before payment.
                (400, r#"{"reason":"call_not_live"}"#.into())
            } else if p == "/status" || p == "/messages/compose" { ops(m, p, b) }
            else { calls(m, p, b) }
        }));
        do_budget_approve(&node.state, 500000, budget::PresetId::Careful).await.unwrap();
        with_book(&node.state, true, |b| b.set_limit(A, false, 50000)).unwrap();
        let offer = do_call_signal(&node.state, A, 400, OFFER, 15000).await.unwrap();
        let spent = budget_now(&node.state).spent_msat;
        let err = do_call_signal(&node.state, A, 403,
            r#"{"v":1,"call_id":"0123456789abcdef0123456789abcdef","reason":"ended"}"#, 6000).await.unwrap_err();
        assert_eq!(err.code, "call_not_live");
        let id = err.operation_id.unwrap();
        assert_eq!(ledger_record(&node, &id)["state"], "unpaid");
        assert_eq!(ledger_record(&node, &offer.operation_id.unwrap())["state"], "settled");
        assert!(pending(&node).is_none());
        assert_eq!(budget_now(&node.state).spent_msat, spent);
        assert_eq!(budget_now(&node.state).unsettled_msat, 0);
        spend_advance(&node.state, true).await.unwrap();
        let receipt = do_payment_keysend(&node.state, &format!("03{}", "cd".repeat(32)), 5000, None, 10000).await.unwrap();
        assert_eq!(receipt.status, "settled");
        assert!(pending(&node).is_none());
        assert_eq!(node.posts().iter().filter(|(p, _)| p == "/payments/keysend").count(), 1);
        assert_eq!(ledger_record(&node, &id)["state"], "unpaid");
    }

    #[tokio::test]
    async fn ledger_success_and_paid_undelivered_are_retained() {
        let (node, _) = ops_fake(|n| { n.script = vec![("paid", false)]; n.settled_incomplete = true; });
        spend_advance(&node.state, true).await.unwrap();
        let err = do_message_send(&node.state, A, false, "gm", 14000, None).await.unwrap_err();
        assert_eq!(err.code, "payment_settled_undelivered");
        let p = pending(&node).unwrap();
        let id = p.operation_id.as_ref().unwrap();
        assert_eq!(ledger_record(&node, id)["state"], "paid_undelivered");
        do_spend_dismiss_undelivered(&node.state, &p.id).unwrap();
        let record = ledger_record(&node, id);
        assert_eq!(record["state"], "settled");
        assert_eq!(record["paid_msat"], 2000);
        assert!(pending(&node).is_none());
        let receipt = do_message_send(&node.state, A, false, "next", 14000, None).await.unwrap();
        let second = receipt.operation_id.unwrap();
        assert_ne!(&second, id);
        assert_eq!(ledger_record(&node, &second)["state"], "settled");
        assert_eq!(ledger_record(&node, id), record);
    }

    #[tokio::test]
    async fn ledger_dismiss_write_failure_keeps_dispatched_operation_id() {
        let (node, _) = ops_fake(|n| { n.script = vec![("paid", false)]; n.settled_incomplete = true; });
        spend_advance(&node.state, true).await.unwrap();
        let error = do_message_send(&node.state, A, false, "gm", 14000, None).await.unwrap_err();
        assert_eq!(error.code, "payment_settled_undelivered");
        let p = pending(&node).unwrap();
        let id = p.operation_id.as_ref().unwrap();
        let record = ledger_record(&node, id);
        let next = journal_file(&node).parent().unwrap().join(format!("ops/{id}.next"));
        std::fs::create_dir(&next).unwrap();
        let error = do_spend_dismiss_undelivered(&node.state, &p.id).unwrap_err();
        assert_eq!(error.code, "spend_unknown");
        assert_eq!(error.operation_id.as_deref(), Some(id.as_str()));
        assert_eq!(ledger_record(&node, id), record);
        assert_eq!(pending(&node).unwrap().id, p.id, "failed dismissal retains the fence");
        assert_eq!(op_ids(&node), [Some(id.clone())], "dismissal never dispatches");
        std::fs::remove_dir(next).unwrap();
        do_spend_dismiss_undelivered(&node.state, &p.id).unwrap();
        assert_eq!(ledger_record(&node, id)["state"], "settled");
        assert!(pending(&node).is_none());
    }

    #[tokio::test]
