            assert_eq!(error.code, "price_quote_unavailable", "{path}: {status}");
            assert_eq!(quote.send_unavailable.as_deref(), Some(error.message.as_str()));
            assert!(!error.message.contains("Upgrade"));
            assert!(!has_all_in_caps(&node.state));
